import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AgendaConfig, User, DayData, LayoutElement, ElementType, PageLayoutType, TextStyleConfig, PageSize, PageOrientation } from '../../types';
import { generateCalendarYear, getMonthName } from '../../core/backend/calendar';
import { generateMonthlyQuotes } from '../../core/backend/ai';
import { calculateDragPosition, calculateResize } from '../../core/logic/interaction';
import { ELEMENT_VARIANTS, AVAILABLE_FONTS } from '../../core/constants/elements';
import { ElementRenderer } from './components/ElementRenderer';

import { 
  Calendar, Printer, LogOut, Moon, Type, 
  Trash2, Move, AlignLeft, AlignCenter, AlignRight, AlignJustify, Layout,
  Square, Circle, Flower, ListTodo, Grid3X3, ArrowDownAZ,
  Settings2, ScanLine, FlipHorizontal, FlipVertical,
  Layers, Upload, ChevronDown, Clock,
  CalendarDays, Palmtree, X, Star, Heart, Leaf,
  ChevronUp, Book, Plus, FileText, Grid, List,
  Type as TypeIcon, CaseUpper, CaseLower,
  PanelTop, PanelBottom, PanelLeft, PanelRight, Columns, Rows, Minus,
  Table as TableIcon,
  ArrowUpToLine, ArrowDownToLine, AlignCenterVertical, 
  AlignStartHorizontal, AlignCenterHorizontal, AlignEndHorizontal, BoxSelect,
  Minimize2, ChevronLeft, ChevronRight, Loader2, Settings, CheckCircle2, Search,
  FileDown, Info
} from 'lucide-react';

interface DashboardProps {
  user: User;
  initialConfig?: Partial<AgendaConfig>;
  onLogout: () => void;
  onConfigure?: () => void;
}

const PAGE_SIZES_MM: Record<PageSize, { width: number; height: number }> = {
    'A4': { width: 210, height: 297 },
    'A5': { width: 148, height: 210 },
    'Letter': { width: 215.9, height: 279.4 }
};

export const Dashboard: React.FC<DashboardProps> = ({ user, initialConfig, onLogout, onConfigure }) => {
  const getDefaultElements = (): LayoutElement[] => [
      { 
          id: '1', 
          name: 'Texto Livre', 
          type: 'text', 
          content: 'Seu texto aqui', 
          x: 10, 
          y: 10, 
          w: 80, 
          h: 10, 
          zIndex: 10, 
          style: { fontSize: 14, fontWeight: 'normal', color: '#000000', textAlign: 'left', fontFamily: 'Inter' } 
      }
  ];

  const [config, setConfig] = useState<AgendaConfig>({
    year: initialConfig?.year || new Date().getFullYear() + 1,
    layoutType: initialConfig?.layoutType || '1_per_page',
    pageSize: initialConfig?.pageSize || 'A5',
    orientation: initialConfig?.orientation || 'portrait',
    includeHolidays: initialConfig?.includeHolidays ?? true,
    includeMoonPhases: initialConfig?.includeMoonPhases ?? false,
    includeQuotes: initialConfig?.includeQuotes ?? false,
    mirrorEvenPages: initialConfig?.mirrorEvenPages ?? true,
    margins: initialConfig?.margins || { top: 15, bottom: 15, inside: 20, outside: 10 },
    elements: initialConfig?.elements && initialConfig.elements.length > 0 ? initialConfig.elements : getDefaultElements(),
    introPages: initialConfig?.introPages || [
        { id: 'intro-1', name: 'Dados Pessoais', elements: [{ id: 'ip1', type: 'text', content: 'DADOS PESSOAIS', name: 'Título', x: 10, y: 10, w: 80, h: 10, zIndex: 1, style: { fontSize: 24, fontWeight: 'bold', textAlign: 'center', color: '#333' } }] }
    ]
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');
  const [showMargins, setShowMargins] = useState(true);
  const [customFonts, setCustomFonts] = useState<string[]>([]);
  const [variantModal, setVariantModal] = useState<{type: ElementType, label: string} | null>(null);
  const [editorViewMode, setEditorViewMode] = useState<'standard' | 'weekend'>('standard');

  const [renderedPreviewCount, setRenderedPreviewCount] = useState(0); 
  const [renderedPrintCount, setRenderedPrintCount] = useState(0); 
  const [printStatus, setPrintStatus] = useState<'idle' | 'generating' | 'ready'>('idle');

  const [showLayers, setShowLayers] = useState(false);
  const [showProperties, setShowProperties] = useState(true);
  const [showAlignment, setShowAlignment] = useState(false);

  const [isDragging, setIsDragging] = useState(false);
  const [resizeDir, setResizeDir] = useState<string | null>(null);
  const [resizingTableCol, setResizingTableCol] = useState<{ elementId: string, colIndex: number } | null>(null);
  const [activeTableCell, setActiveTableCell] = useState<{ r: number, c: number } | null>(null);

  const [fontControlTab, setFontControlTab] = useState<'title' | 'weekDays' | 'days' | 'highlight'>('title');

  const [editMode, setEditMode] = useState<'daily' | 'intro'>('daily');
  const [currentIntroPageId, setCurrentIntroPageId] = useState<string | null>(config.introPages[0]?.id || null);

  const dragRef = useRef<any>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
      if (activeTab === 'preview') {
          if (renderedPreviewCount < generatedData.length) {
              const timer = setTimeout(() => {
                  setRenderedPreviewCount(prev => Math.min(prev + 20, generatedData.length));
              }, 10);
              return () => clearTimeout(timer);
          }
      } else {
          if (renderedPreviewCount > 0) setRenderedPreviewCount(0);
      }
  }, [activeTab, renderedPreviewCount, generatedData.length]);

  const handlePrintRequest = () => {
      setPrintStatus('generating');
      setRenderedPrintCount(0);
  };

  useEffect(() => {
      if (printStatus === 'generating') {
          const timer = setTimeout(() => {
              if (renderedPrintCount < generatedData.length) {
                  setRenderedPrintCount(prev => Math.min(prev + 50, generatedData.length));
              } else {
                  setTimeout(() => setPrintStatus('ready'), 500);
              }
          }, 50);
          return () => clearTimeout(timer);
      }
  }, [printStatus, renderedPrintCount, generatedData.length]);

  const executePrint = useCallback(() => {
      window.print();
  }, []);

  const cancelPrint = () => {
      setPrintStatus('idle');
      setRenderedPrintCount(0);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Delete' || e.key === 'Backspace') {
            const activeElement = document.activeElement;
            const isInputActive = activeElement && (
                activeElement.tagName === 'INPUT' || 
                activeElement.tagName === 'TEXTAREA' || 
                (activeElement as HTMLElement).isContentEditable
            );

            if (!isInputActive && selectedId) {
                removeElement(selectedId);
            }
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedId, config]); 

  const getPageDimensions = () => {
      const base = PAGE_SIZES_MM[config.pageSize];
      if (config.orientation === 'portrait') return base;
      return { width: base.height, height: base.width };
  };

  const { width: PAGE_WIDTH_MM, height: PAGE_HEIGHT_MM } = getPageDimensions();
  const EDITOR_WIDTH_PX = 400; 
  const EDITOR_SCALE = EDITOR_WIDTH_PX / PAGE_WIDTH_MM;
  const EDITOR_HEIGHT_PX = PAGE_HEIGHT_MM * EDITOR_SCALE;

  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  useEffect(() => {
    if (config.includeQuotes && quotes.length === 0) {
       generateMonthlyQuotes(config.year).then(setQuotes);
    }
  }, [config.includeQuotes, config.year]);

  useEffect(() => {
      if (selectedId) setShowProperties(true);
  }, [selectedId]);

  const getActiveElements = () => {
      if (editMode === 'daily') return config.elements;
      if (editMode === 'intro' && currentIntroPageId) {
          return config.introPages.find(p => p.id === currentIntroPageId)?.elements || [];
      }
      return [];
  };

  const updateActiveElements = (newElements: LayoutElement[]) => {
      if (editMode === 'daily') {
          setConfig(prev => ({ ...prev, elements: newElements }));
      } else if (editMode === 'intro' && currentIntroPageId) {
          setConfig(prev => ({
              ...prev,
              introPages: prev.introPages.map(p => p.id === currentIntroPageId ? { ...p, elements: newElements } : p)
          }));
      }
  };

  const alignElement = (type: 'left' | 'center' | 'right' | 'top' | 'middle' | 'bottom') => {
      if (!selectedId) return;
      const activeList = getActiveElements();
      const element = activeList.find(el => el.id === selectedId);
      if (!element) return;
      const newEl = { ...element };
      switch(type) {
          case 'left': newEl.x = 0; break;
          case 'center': newEl.x = 50 - (newEl.w / 2); break;
          case 'right': newEl.x = 100 - newEl.w; break;
          case 'top': newEl.y = 0; break;
          case 'middle': newEl.y = 50 - (newEl.h / 2); break;
          case 'bottom': newEl.y = 100 - newEl.h; break;
      }
      updateActiveElements(activeList.map(el => el.id === selectedId ? newEl : el));
  };

  const fitToText = () => {
      if (!selectedId) return;
      const activeList = getActiveElements();
      const element = activeList.find(el => el.id === selectedId);
      if (!element || !element.content) return;
      const charCount = element.content.length;
      const fontSize = element.style.fontSize || 14;
      const estWidthPx = charCount * (fontSize * 0.6); 
      const estWidthPercent = (estWidthPx / EDITOR_WIDTH_PX) * 100;
      const newWidth = Math.min(90, Math.max(10, estWidthPercent));
      const newHeight = Math.max(5, (fontSize * 1.5 * (Math.ceil(estWidthPercent/90)) / EDITOR_HEIGHT_PX) * 100);
      updateActiveElements(activeList.map(el => el.id === selectedId ? { ...el, w: newWidth, h: newHeight } : el));
  };

  const addIntroPage = () => {
      const newPage = {
          id: Math.random().toString(36).substr(2, 9),
          name: `Página ${config.introPages.length + 1}`,
          elements: []
      };
      setConfig(prev => ({ ...prev, introPages: [...prev.introPages, newPage] }));
      setCurrentIntroPageId(newPage.id);
  };

  const renameIntroPage = (id: string, name: string) => {
      setConfig(prev => ({
          ...prev,
          introPages: prev.introPages.map(p => p.id === id ? { ...p, name } : p)
      }));
  };

  const deleteIntroPage = (id: string) => {
      setConfig(prev => {
          const newPages = prev.introPages.filter(p => p.id !== id);
          if (currentIntroPageId === id) {
              setCurrentIntroPageId(newPages[0]?.id || null);
          }
          return { ...prev, introPages: newPages };
      });
  };

  const handleScrollToMonth = (monthIndex: number) => {
      if (activeTab !== 'preview') return;
      let dayIndex = 0;
      for (let i = 0; i < generatedData.length; i++) {
          if (generatedData[i].month === monthIndex) {
              dayIndex = i;
              break;
          }
      }
      let pageNumber = config.introPages.length + 1;
      if (config.layoutType === '1_per_page') {
          pageNumber += dayIndex;
      } else if (config.layoutType === '2_per_page') {
          pageNumber += Math.floor(dayIndex / 2);
      } else if (config.layoutType === '1_per_page_weekend_shared') {
          let currentDay = 0;
          let p = config.introPages.length + 1;
          while (currentDay < dayIndex) {
              const day = generatedData[currentDay];
              if (!day) break;
              const isWeekend = day.dayOfWeek === 6;
              if (isWeekend) currentDay += 2; else currentDay += 1;
              p++;
          }
          pageNumber = p;
      }
      const element = document.getElementById(`preview-page-${pageNumber}`);
      if (element) element.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const addElement = (type: ElementType, label: string, styleOverride: any = {}, sizeOverride: any = {}) => {
    const activeList = getActiveElements();
    const newElement: LayoutElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      name: `${label} ${activeList.length + 1}`,
      x: 35, y: 40, w: sizeOverride.w || 20, h: sizeOverride.h || 10, zIndex: activeList.length + 1,
      style: { fontSize: 14, color: '#000000', textAlign: 'left', lineSpacing: 24, borderColor: '#000000', borderWidth: 1, backgroundColor: 'transparent', rotation: 0, opacity: 1, flipX: false, flipY: false, fontFamily: 'Inter', showTimes: false, startHour: 7, borderStyle: 'solid', ...styleOverride }
    };

    if (type === 'text') newElement.content = "Novo Texto";

    const defaultCalendarStyle = {
        title: { fontSize: 10, fontFamily: 'Inter', fontWeight: 'bold', color: '#000', textAlign: 'center' as const, textTransform: 'uppercase' as const, letterSpacing: 1 },
        weekDays: { fontSize: 7, fontFamily: 'Inter', fontWeight: 'bold', color: '#666', textAlign: 'center' as const, textTransform: 'uppercase' as const, letterSpacing: 0 },
        days: { fontSize: 8, fontFamily: 'Inter', fontWeight: 'normal', color: '#333', textAlign: 'center' as const, textTransform: 'none' as const, letterSpacing: 0 },
        grid: { 
            borderColor: '#dddddd', borderWidth: 0.5, cellBackgroundColor: 'transparent', headerBackgroundColor: 'transparent',
            borders: { top: false, bottom: false, left: false, right: false, insideHorizontal: false, insideVertical: false, headerSeparator: true }
        },
        specialDays: {
            highlightSundays: true,
            highlightHolidays: false,
            style: { fontSize: 8, fontFamily: 'Inter', fontWeight: 'bold', color: '#dc2626', textAlign: 'center' as const, textTransform: 'none' as const, letterSpacing: 0, backgroundColor: 'transparent' }
        }
    };

    if (!sizeOverride.w) {
        if (type === 'lines') { newElement.w = 80; newElement.h = 40; newElement.x = 10; newElement.style.borderWidth = 0; }
        if (type === 'box') { newElement.w = 30; newElement.h = 15; newElement.style.backgroundColor = '#f3f4f6'; newElement.style.borderWidth = 0; }
        if (type === 'circle') { newElement.w = 15; newElement.h = 15; newElement.style.backgroundColor = '#e0e7ff'; newElement.style.borderRadius = 999; newElement.style.borderWidth = 0; }
        if (type === 'day_number') { newElement.w = 15; newElement.h = 10; newElement.style.fontSize = 32; newElement.style.fontWeight = 'bold'; newElement.style.borderWidth = 0; }
        if (type === 'mini_calendar') { 
            newElement.w = 25; newElement.h = 18; 
            newElement.style.calendarOffset = 0;
            newElement.style.borderWidth = 0;
            newElement.style.fullCalendar = defaultCalendarStyle;
        }
        if (type === 'full_calendar') { 
            newElement.w = 90; newElement.h = 80; newElement.x = 5; newElement.y = 10; 
            newElement.style.borderWidth = 0; newElement.style.monthsPerRow = 3; newElement.style.gap = 15; 
            newElement.style.fullCalendar = {
                ...defaultCalendarStyle,
                title: { ...defaultCalendarStyle.title, fontSize: 14 },
                weekDays: { ...defaultCalendarStyle.weekDays, fontSize: 9 },
                days: { ...defaultCalendarStyle.days, fontSize: 10 },
                specialDays: { ...defaultCalendarStyle.specialDays, style: { ...defaultCalendarStyle.specialDays.style, fontSize: 10, backgroundColor: '#fee2e2' } }
            };
        }
        if (type === 'table') {
            newElement.w = 80; newElement.h = 40; newElement.x = 10;
            newElement.style.borderWidth = 1;
            newElement.style.borderColor = '#d1d5db';
            newElement.style.table = {
                rows: 10,
                cols: 2,
                borderColor: '#d1d5db',
                borderWidth: 1,
                headerRow: true,
                columnWidths: [50, 50],
                cellContent: {},
                rowHeight: 30, // Default row height
                textStyle: { fontFamily: 'Inter', fontSize: 10, fontWeight: 'normal', color: '#4b5563', textAlign: 'left', verticalAlign: 'top', textTransform: 'none', letterSpacing: 0 },
                rowStyles: {}, colStyles: {},
                borders: { top: true, bottom: true, left: true, right: true, insideHorizontal: true, insideVertical: true, headerSeparator: true }
            };
        }
    }

    updateActiveElements([...activeList, newElement]);
    setSelectedId(newElement.id);
    setVariantModal(null);
  };

  const removeElement = (id: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.filter(e => e.id !== id));
    setSelectedId(null);
  };

  const moveLayer = (id: string, direction: 'up' | 'down') => {
      const activeList = getActiveElements();
      const index = activeList.findIndex(e => e.id === id);
      if (index === -1) return;
      if (direction === 'up' && index === activeList.length - 1) return;
      if (direction === 'down' && index === 0) return;
      const newElements = [...activeList];
      const swapIndex = direction === 'up' ? index + 1 : index - 1;
      [newElements[index], newElements[swapIndex]] = [newElements[swapIndex], newElements[index]];
      const updatedElements = newElements.map((el, i) => ({ ...el, zIndex: i + 1 }));
      updateActiveElements(updatedElements);
  };

  const updateElementStyle = (id: string, styleUpdate: any) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, style: { ...e.style, ...styleUpdate } } : e));
  };

  const updateElementContent = (id: string, content: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, content } : e));
  };

  const updateTableConfig = (id: string, tableUpdate: any) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if (!element || !element.style.table) return;
      let newTableStyle = { ...element.style.table, ...tableUpdate };
      if (tableUpdate.cols) {
          const newCols = tableUpdate.cols;
          const oldCols = element.style.table.cols;
          if (newCols > oldCols) newTableStyle.columnWidths = Array(newCols).fill(100 / newCols);
          else if (newCols < oldCols) newTableStyle.columnWidths = newTableStyle.columnWidths?.slice(0, newCols) || Array(newCols).fill(100/newCols);
      }
      updateElementStyle(id, { table: newTableStyle });
  }

  const toggleTableBorder = (borderKey: keyof NonNullable<Required<LayoutElement['style']['table']>['borders']>) => {
      const activeList = getActiveElements();
      const selectedElement = activeList.find(e => e.id === selectedId);
      if (!selectedElement || !selectedElement.style.table) return;
      const currentBorders = selectedElement.style.table.borders || { top: true, bottom: true, left: true, right: true, insideHorizontal: true, insideVertical: true, headerSeparator: true };
      updateTableConfig(selectedElement.id, { borders: { ...currentBorders, [borderKey]: !currentBorders[borderKey] } });
  };

  const updateTableCell = (id: string, rowIndex: number, colIndex: number, text: string) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if (!element || !element.style.table) return;
      const key = `${rowIndex}-${colIndex}`;
      const newContent = { ...(element.style.table.cellContent || {}), [key]: text };
      updateElementStyle(id, { table: { ...element.style.table, cellContent: newContent } });
  }

  const updateFullCalendarStyle = (id: string, section: 'title' | 'weekDays' | 'days' | 'highlight', styleUpdate: Partial<TextStyleConfig>) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if(!element || !element.style.fullCalendar) return;
      if (section === 'highlight') {
          const newSpecialDays = { ...element.style.fullCalendar.specialDays, style: { ...element.style.fullCalendar.specialDays?.style, ...styleUpdate } };
          updateElementStyle(id, { fullCalendar: { ...element.style.fullCalendar, specialDays: newSpecialDays } });
          return;
      }
      const newFullCalendar = { ...element.style.fullCalendar, [section]: { ...element.style.fullCalendar[section], ...styleUpdate } };
      updateElementStyle(id, { fullCalendar: newFullCalendar });
  };

  const updateElementName = (id: string, name: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, name } : e));
  };

  const handleInteractionStart = (e: React.MouseEvent, id: string, dir: string | null = null) => {
    if (activeTab === 'preview') return;
    e.stopPropagation();
    const activeList = getActiveElements();
    const element = activeList.find(el => el.id === id);
    if (!element) return;
    setSelectedId(id);
    dragRef.current = { startX: e.clientX, startY: e.clientY, initialX: element.x, initialY: element.y, initialW: element.w, initialH: element.h };
    if (dir) setResizeDir(dir); else setIsDragging(true);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (resizingTableCol && dragRef.current && selectedId) {
        const { elementId, colIndex } = resizingTableCol;
        const activeList = getActiveElements();
        const element = activeList.find(el => el.id === elementId);
        if (element && element.style.table && element.style.table.columnWidths) {
            const tableWidthPx = (element.w / 100) * EDITOR_WIDTH_PX;
            const deltaX = e.clientX - dragRef.current.startX;
            const deltaPercent = (deltaX / tableWidthPx) * 100;
            const currentWidths = [...element.style.table.columnWidths];
            const nextColIndex = colIndex + 1;
            if (nextColIndex < currentWidths.length) {
                const newCurrentColWidth = Math.max(5, currentWidths[colIndex] + deltaPercent);
                const newNextColWidth = Math.max(5, currentWidths[nextColIndex] - deltaPercent);
                if (newCurrentColWidth >= 5 && newNextColWidth >= 5) {
                    currentWidths[colIndex] = newCurrentColWidth;
                    currentWidths[nextColIndex] = newNextColWidth;
                    const total = currentWidths.reduce((a, b) => a + b, 0);
                    const normalized = currentWidths.map(w => (w / total) * 100);
                    updateElementStyle(elementId, { table: { ...element.style.table, columnWidths: normalized } });
                    dragRef.current.startX = e.clientX;
                }
            }
        }
        return;
    }

    if ((!isDragging && !resizeDir) || !dragRef.current || !selectedId || !editorRef.current) return;
    const editorRect = editorRef.current.getBoundingClientRect();
    const deltaX = e.clientX - dragRef.current.startX;
    const deltaY = e.clientY - dragRef.current.startY;
    const activeList = getActiveElements();
    let newElementConfig = { ...activeList.find(el => el.id === selectedId)! };
    if (isDragging) {
        const { x, y } = calculateDragPosition(deltaX, deltaY, dragRef.current.initialX, dragRef.current.initialY, editorRect.width, editorRect.height);
        newElementConfig.x = x; newElementConfig.y = y;
    } else if (resizeDir) {
        const { x, y, w, h } = calculateResize(deltaX, deltaY, dragRef.current.initialX, dragRef.current.initialY, dragRef.current.initialW, dragRef.current.initialH, editorRect.width, editorRect.height, resizeDir);
        newElementConfig.x = x; newElementConfig.y = y; newElementConfig.w = w; newElementConfig.h = h;
    }
    updateActiveElements(activeList.map(el => el.id === selectedId ? newElementConfig : el));
  };

  const handleMouseUp = () => { setIsDragging(false); setResizeDir(null); setResizingTableCol(null); dragRef.current = null; };

  const renderResizeHandle = (cursor: string, dir: string) => {
      const pos: React.CSSProperties = { position: 'absolute', width: '8px', height: '8px', backgroundColor: 'white', border: '1px solid #4f46e5', borderRadius: '50%', zIndex: 50 };
      switch(dir) {
          case 'nw': pos.top = '-4px'; pos.left = '-4px'; break;
          case 'n':  pos.top = '-4px'; pos.left = '50%'; pos.transform = 'translateX(-50%)'; break;
          case 'ne': pos.top = '-4px'; pos.right = '-4px'; break;
          case 'e':  pos.top = '50%'; pos.right = '-4px'; pos.transform = 'translateY(-50%)'; break;
          case 'se': pos.bottom = '-4px'; pos.right = '-4px'; break;
          case 's':  pos.bottom = '-4px'; pos.left = '50%'; pos.transform = 'translateX(-50%)'; break;
          case 'sw': pos.bottom = '-4px'; pos.left = '-4px'; break;
          case 'w':  pos.top = '50%'; pos.left = '-4px'; pos.transform = 'translateY(-50%)'; break;
      }
      return <div className="no-print" style={{ ...pos, cursor }} onMouseDown={(e) => handleInteractionStart(e, selectedId!, dir)} />;
  }

  const renderTemplate = (elements: LayoutElement[], day: DayData | null, isEditor: boolean = false, attachRef: boolean = false) => {
    const d = day || { dayOfMonth: 24, month: 7, year: config.year, dayOfWeek: 3, holiday: 'Feriado', moonPhase: 'Lua cheia', date: new Date() } as DayData;
    return (
      <div ref={attachRef ? editorRef : null} className={`relative overflow-hidden w-full h-full`} onMouseMove={isEditor ? handleMouseMove : undefined} onMouseUp={isEditor ? handleMouseUp : undefined} onMouseLeave={isEditor ? handleMouseUp : undefined}>
        {elements.map(el => {
          const isSelected = isEditor && selectedId === el.id;
          const wrapperStyle: React.CSSProperties = { left: `${el.x}%`, top: `${el.y}%`, width: `${el.w}%`, height: `${el.h}%`, zIndex: el.zIndex, transform: `rotate(${el.style.rotation || 0}deg) scaleX(${el.style.flipX ? -1 : 1}) scaleY(${el.style.flipY ? -1 : 1})` };
          const containerClass = `absolute group ${isSelected ? 'ring-2 ring-indigo-500 z-50' : 'hover:ring-1 hover:ring-indigo-300'}`;
          const isWrapperType = ['lines','box','circle','vector_flower','note_grid','habit_tracker','mini_calendar','full_calendar','table'].includes(el.type);
          return (
            <div key={el.id} onMouseDown={(e) => handleInteractionStart(e, el.id)} className={containerClass} style={wrapperStyle}>
                {isSelected && <>{['nw','n','ne','e','se','s','sw','w'].map(d => renderResizeHandle(d+'-resize', d))}</>}
                <div className={`w-full h-full relative ${isWrapperType ? 'overflow-hidden flex flex-col' : 'flex items-center'}`} style={{ justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start'), ...(!isWrapperType ? el.style : {}) }}>
                    <ElementRenderer 
                        element={el} 
                        dayData={d} 
                        quote={quotes[d.month]} 
                        isEditor={isEditor} 
                        isSelected={isSelected}
                        onContentChange={updateElementContent}
                        onTableResizeStart={(e, eid, ci) => { e.stopPropagation(); setSelectedId(eid); setResizingTableCol({ elementId: eid, colIndex: ci }); dragRef.current = { startX: e.clientX, startY: e.clientY }; }}
                        onTableCellChange={updateTableCell}
                        onTableCellFocus={(eid, r, c) => { setSelectedId(eid); setActiveTableCell({ r, c }); }}
                    />
                </div>
            </div>
          );
        })}
      </div>
    );
  };

  const getMirroredElements = (elements: LayoutElement[]): LayoutElement[] => {
      if (!config.mirrorEvenPages) return elements;
      return elements.map(el => {
          const newX = 100 - el.x - el.w;
          let newTextAlign = el.style.textAlign;
          if (newTextAlign === 'left') newTextAlign = 'right'; else if (newTextAlign === 'right') newTextAlign = 'left';
          return { ...el, x: newX, style: { ...el.style, textAlign: newTextAlign } };
      });
  };

  const renderEditorPage = () => {
    const paddingStyle = { paddingTop: `${config.margins.top * EDITOR_SCALE}px`, paddingBottom: `${config.margins.bottom * EDITOR_SCALE}px`, paddingLeft: `${config.margins.inside * EDITOR_SCALE}px`, paddingRight: `${config.margins.outside * EDITOR_SCALE}px` };
    const containerStyle = { width: `${EDITOR_WIDTH_PX}px`, height: `${EDITOR_HEIGHT_PX}px`, ...paddingStyle };
    const usefulAreaClass = `w-full h-full relative ${showMargins ? 'outline outline-1 outline-dashed outline-indigo-300' : ''}`;
    if (editMode === 'intro') return <div className="bg-white shadow-2xl relative transition-all flex flex-col" style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(getActiveElements(), null, true, true)}</div></div>;
    const activeElements = config.elements;
    if (config.layoutType === '1_per_page') return <div className="bg-white shadow-2xl relative transition-all flex flex-col" style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(activeElements, null, true, true)}</div></div>;
    if (config.layoutType === '2_per_page') return <div className="bg-white shadow-2xl relative transition-all flex flex-col" style={containerStyle}><div className={`${usefulAreaClass} flex flex-col`}><div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(activeElements, null, true, true)}</div><div className="flex-1 relative overflow-hidden">{renderTemplate(activeElements, null, true, false)}</div></div></div>;
    if (config.layoutType === '1_per_page_weekend_shared') return editorViewMode === 'standard' ? <div className="bg-white shadow-2xl relative transition-all flex flex-col" style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(activeElements, null, true, true)}</div></div> : <div className="bg-white shadow-2xl relative transition-all flex flex-col" style={containerStyle}><div className={`${usefulAreaClass} flex flex-col`}><div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(activeElements, null, true, true)}</div><div className="flex-1 relative overflow-hidden">{renderTemplate(activeElements, null, true, false)}</div></div></div>;
    return null;
  };

  const renderPrintLayout = (maxRenderCount?: number) => {
    const pages: React.ReactNode[] = [];
    const pageStyle = { width: `${PAGE_WIDTH_MM}mm`, height: `${PAGE_HEIGHT_MM}mm` };
    const borderStyle = showMargins ? 'border border-indigo-200 border-dashed' : '';
    let pageCount = 0;
    const renderPageContainer = (children: React.ReactNode, key: string | number) => {
        pageCount++;
        const isEven = pageCount % 2 === 0;
        const marginLeft = isEven ? config.margins.outside : config.margins.inside;
        const marginRight = isEven ? config.margins.inside : config.margins.outside;
        const pagePadding = `${config.margins.top}mm ${marginRight}mm ${config.margins.bottom}mm ${marginLeft}mm`;
        return (
            <div id={`preview-page-${pageCount}`} key={key} className="bg-white shadow print:shadow-none print-break-page relative box-border overflow-hidden mx-auto mb-8 print:mb-0 shrink-0" style={{ ...pageStyle, padding: pagePadding }}>
                <div className={`w-full h-full relative ${borderStyle} print:border-none`}>{children}</div>
                <div className={`absolute bottom-1 text-[8px] text-gray-300 no-print ${isEven ? 'left-2' : 'right-2'}`}>Pág {pageCount}</div>
            </div>
        );
    };
    config.introPages.forEach(page => {
        const isEven = (pageCount + 1) % 2 === 0;
        const elementsToRender = isEven ? getMirroredElements(page.elements) : page.elements;
        pages.push(renderPageContainer(renderTemplate(elementsToRender, null, false), page.id));
    });
    const days = maxRenderCount !== undefined ? generatedData.slice(0, maxRenderCount) : generatedData;
    if (config.layoutType === '1_per_page') {
        days.forEach(day => { 
            const isEven = (pageCount + 1) % 2 === 0;
            pages.push(renderPageContainer(renderTemplate(isEven ? getMirroredElements(config.elements) : config.elements, day, false), day.date.toISOString()));
        });
    } else if (config.layoutType === '2_per_page') {
        for (let i = 0; i < days.length; i += 2) {
            const isEven = (pageCount + 1) % 2 === 0;
            const els = isEven ? getMirroredElements(config.elements) : config.elements;
            pages.push(renderPageContainer(<div className="flex flex-col h-full"><div className="flex-1 relative border-b border-dashed border-gray-200 pb-2 mb-2 overflow-hidden">{renderTemplate(els, days[i], false)}</div><div className="flex-1 relative pt-2 overflow-hidden">{days[i+1] ? renderTemplate(els, days[i+1], false) : null}</div></div>, i));
        }
    } else if (config.layoutType === '1_per_page_weekend_shared') {
        let i = 0;
        while (i < days.length) {
            const isWeekend = days[i].dayOfWeek === 6;
            const isEven = (pageCount + 1) % 2 === 0;
            const els = isEven ? getMirroredElements(config.elements) : config.elements;
            if (isWeekend) {
                pages.push(renderPageContainer(<div className="flex flex-col h-full"><div className="flex-1 relative border-b border-dashed border-gray-300 pb-2 mb-2 overflow-hidden">{renderTemplate(els, days[i], false)}</div><div className="flex-1 relative pt-2 overflow-hidden">{days[i+1] ? renderTemplate(els, days[i+1], false) : null}</div></div>, `we-${i}`));
                i += 2;
            } else {
                pages.push(renderPageContainer(renderTemplate(els, days[i], false), days[i].date.toISOString()));
                i += 1;
            }
        }
    }
    return pages;
  };

  const renderTypographyControls = (values: TextStyleConfig, onChange: (update: Partial<TextStyleConfig>) => void) => (
      <div className="space-y-4">
           <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Fonte</label><div className="relative"><select value={values.fontFamily} onChange={(e) => onChange({ fontFamily: e.target.value })} className="w-full text-xs p-1.5 border border-gray-200 rounded bg-white">{AVAILABLE_FONTS.map(font => (<option key={font} value={font}>{font}</option>))}</select><ChevronDown className="w-3 h-3 text-gray-400 absolute right-2 top-2.5 pointer-events-none" /></div></div>
           <div className="flex gap-2"><div className="flex-1"><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Tamanho</label><input type="number" min="4" max="100" value={values.fontSize} onChange={(e) => onChange({ fontSize: parseInt(e.target.value) })} className="w-full text-xs p-1.5 border border-gray-200 rounded" /></div><div className="flex-1"><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Cor Texto</label><input type="color" value={values.color} onChange={(e) => onChange({ color: e.target.value })} className="w-full h-8 p-0 border border-gray-200 rounded" /></div></div>
           <div className="flex gap-2"><div className="flex-1"><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Peso</label><select value={values.fontWeight} onChange={(e) => onChange({ fontWeight: e.target.value })} className="w-full text-xs p-1.5 border border-gray-200 rounded"><option value="normal">Normal</option><option value="bold">Bold</option><option value="300">Light</option></select></div><div className="flex-1"><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Tracking</label><input type="number" step="0.5" value={values.letterSpacing} onChange={(e) => onChange({ letterSpacing: parseFloat(e.target.value) })} className="w-full text-xs p-1.5 border border-gray-200 rounded" /></div></div>
           <div className="grid grid-cols-4 gap-1 border border-gray-200 rounded overflow-hidden">
                <button onClick={() => onChange({ textAlign: 'left' })} className={`p-2 ${values.textAlign === 'left' ? 'bg-indigo-50 text-indigo-600' : 'text-gray-500'}`}><AlignLeft className="w-4 h-4 mx-auto"/></button>
                <button onClick={() => onChange({ textAlign: 'center' })} className={`p-2 ${values.textAlign === 'center' ? 'bg-indigo-50 text-indigo-600' : 'text-gray-500'}`}><AlignCenter className="w-4 h-4 mx-auto"/></button>
                <button onClick={() => onChange({ textAlign: 'right' })} className={`p-2 ${values.textAlign === 'right' ? 'bg-indigo-50 text-indigo-600' : 'text-gray-500'}`}><AlignRight className="w-4 h-4 mx-auto"/></button>
                <button onClick={() => onChange({ textAlign: 'justify' })} className={`p-2 ${values.textAlign === 'justify' ? 'bg-indigo-50 text-indigo-600' : 'text-gray-500'}`}><AlignJustify className="w-4 h-4 mx-auto"/></button>
           </div>
      </div>
  );

  const totalPages = config.introPages.length + generatedData.length; 
  const progressPercent = Math.min(100, Math.round(((config.introPages.length + renderedPrintCount) / totalPages) * 100));

  return (
    <div className="h-screen flex flex-col bg-gray-100 overflow-hidden relative print:overflow-visible print:h-auto print:static">
      <style>{`
        @media print {
          body * { visibility: hidden; }
          #print-container, #print-container * { visibility: visible; }
          #print-container { position: absolute; left: 0; top: 0; width: 100%; }
          .no-print { display: none !important; }
          .print-break-page { page-break-after: always; break-after: page; }
        }
      `}</style>

      {printStatus !== 'idle' && (
          <div id="print-container" className="absolute top-0 left-0 -z-50 opacity-0 print:opacity-100 print:z-50 pointer-events-none print:pointer-events-auto">
              {renderPrintLayout(renderedPrintCount)}
          </div>
      )}

      {printStatus !== 'idle' && (
          <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-md flex items-center justify-center flex-col text-white no-print p-6">
              {printStatus === 'generating' ? (
                  <div className="w-full max-w-md bg-white/10 p-6 rounded-2xl border border-white/20 backdrop-blur-xl flex flex-col items-center">
                        <Loader2 className="w-12 h-12 animate-spin mb-4 text-indigo-400" />
                        <h2 className="text-xl font-bold mb-1">Gerando Documento...</h2>
                        <div className="w-full h-3 bg-white/10 rounded-full overflow-hidden mt-4 mb-6"><div className="h-full bg-indigo-500 transition-all duration-300" style={{ width: `${progressPercent}%` }}></div></div>
                        <button onClick={cancelPrint} className="w-full py-2 bg-white/10 hover:bg-white/20 rounded">Cancelar</button>
                  </div>
              ) : (
                  <div className="bg-white p-8 rounded-2xl shadow-2xl flex flex-col items-center text-gray-800 animate-in zoom-in duration-300">
                      <FileDown className="w-12 h-12 text-indigo-600 mb-4" />
                      <h2 className="text-2xl font-bold mb-2">Arquivo Pronto</h2>
                      <div className="flex gap-3 mt-6">
                          <button onClick={cancelPrint} className="py-2 px-6 rounded bg-gray-100 text-gray-700">Cancelar</button>
                          <button onClick={executePrint} className="py-2 px-6 rounded bg-indigo-600 text-white font-bold">Baixar PDF</button>
                      </div>
                  </div>
              )}
          </div>
      )}

      {variantModal && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/20 backdrop-blur-sm no-print" onClick={() => setVariantModal(null)}>
              <div className="bg-white rounded-lg shadow-2xl w-[500px] m-4 flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
                  <div className="flex items-center justify-between p-4 border-b"><h3 className="font-bold uppercase text-sm">Escolha o estilo</h3><button onClick={() => setVariantModal(null)}><X className="w-5 h-5"/></button></div>
                  <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto max-h-[60vh]">
                      {ELEMENT_VARIANTS[variantModal.type]?.map((v, i) => (
                          <div key={i} onClick={() => addElement(variantModal.type, variantModal.label, v.styleOverride, v.defaultSize)} className="border rounded-lg p-4 hover:bg-indigo-50 cursor-pointer transition-all">
                              <div className="font-bold text-sm">{v.name}</div><div className="text-xs text-gray-400">{v.description}</div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      )}

      <div className="flex-1 flex flex-col overflow-hidden no-print">
          <header className="bg-white border-b h-14 flex items-center justify-between px-4 z-20 shrink-0">
            <div className="flex items-center space-x-2 font-bold text-gray-800"><Calendar className="h-5 w-5 text-indigo-600" /><span>AgendaMaster AI</span></div>
            <div className="flex items-center space-x-2 bg-gray-100 p-1 rounded-lg"><button onClick={() => setActiveTab('editor')} className={`px-4 py-1.5 text-xs font-medium rounded-md ${activeTab === 'editor' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Editor</button><button onClick={() => setActiveTab('preview')} className={`px-4 py-1.5 text-xs font-medium rounded-md ${activeTab === 'preview' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Visualizar</button></div>
            <div className="flex items-center space-x-3">
                <button onClick={() => setShowAlignment(!showAlignment)} className={`p-1.5 rounded-md ${showAlignment ? 'bg-indigo-50 text-indigo-600' : 'text-gray-400'}`}><BoxSelect className="w-5 h-5" /></button>
                <button onClick={() => setShowLayers(!showLayers)} className={`p-1.5 rounded-md ${showLayers ? 'bg-indigo-50 text-indigo-600' : 'text-gray-400'}`}><Layers className="w-5 h-5" /></button>
                <button onClick={handlePrintRequest} disabled={printStatus !== 'idle'} className="bg-indigo-600 text-white px-4 py-1.5 rounded text-xs font-bold flex items-center gap-2"><FileDown className="w-4 h-4" /> Baixar PDF</button>
                <button onClick={onLogout} className="text-gray-400 hover:text-red-500"><LogOut className="w-4 h-4" /></button>
            </div>
          </header>

          <div className="flex-1 flex overflow-hidden">
            <aside className="w-72 bg-white border-r flex flex-col shrink-0 overflow-y-auto custom-scrollbar">
                <div className="p-4 border-b">
                    <div className="flex space-x-1 bg-gray-100 p-1 rounded-lg">
                        <button onClick={() => { setEditMode('daily'); setSelectedId(null); }} className={`flex-1 py-1.5 text-[10px] font-bold uppercase rounded-md ${editMode === 'daily' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Template</button>
                        <button onClick={() => { setEditMode('intro'); setSelectedId(null); }} className={`flex-1 py-1.5 text-[10px] font-bold uppercase rounded-md ${editMode === 'intro' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Iniciais</button>
                    </div>
                </div>
                <div className="p-4 flex-1">
                    <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Elementos</h3>
                    <div className="grid grid-cols-4 gap-2">
                        {editMode === 'daily' && (<><button onClick={() => setVariantModal({type: 'day_number', label: 'Número'})} className="h-10 border rounded flex items-center justify-center hover:bg-indigo-50 font-bold text-xs">24</button><button onClick={() => setVariantModal({type: 'day_name', label: 'Dia'})} className="h-10 border rounded flex items-center justify-center hover:bg-indigo-50 font-bold text-[10px]">SEG</button></>)}
                        <button onClick={() => addElement('text', 'Texto')} className="h-10 border rounded flex items-center justify-center hover:bg-indigo-50"><Type className="w-4 h-4"/></button>
                        <button onClick={() => setVariantModal({type: 'lines', label: 'Pautas'})} className="h-10 border rounded flex items-center justify-center hover:bg-indigo-50"><ListTodo className="w-4 h-4"/></button>
                        <button onClick={() => addElement('mini_calendar', 'Calendário')} className="h-10 border rounded flex items-center justify-center hover:bg-indigo-50"><CalendarDays className="w-4 h-4"/></button>
                        <button onClick={() => addElement('table', 'Tabela')} className="h-10 border rounded flex items-center justify-center hover:bg-indigo-50"><TableIcon className="w-4 h-4"/></button>
                    </div>
                </div>
            </aside>

            <main className="flex-1 bg-gray-200 overflow-hidden relative flex flex-col items-center">
                {activeTab === 'editor' && (
                    <div className="flex-1 w-full flex flex-col items-center p-4 overflow-hidden relative">
                        {showAlignment && (
                            <div className="absolute top-4 right-[300px] bg-white rounded-lg shadow-xl p-2 z-40 border grid grid-cols-3 gap-1">
                                <button onClick={() => alignElement('left')} className="p-2 hover:bg-gray-100 rounded"><AlignStartHorizontal className="w-4 h-4"/></button>
                                <button onClick={() => alignElement('center')} className="p-2 hover:bg-gray-100 rounded"><AlignCenterHorizontal className="w-4 h-4"/></button>
                                <button onClick={() => alignElement('right')} className="p-2 hover:bg-gray-100 rounded"><AlignEndHorizontal className="w-4 h-4"/></button>
                            </div>
                        )}
                        {showProperties && selectedId && (
                            <div className="absolute right-4 top-4 w-72 bg-white rounded-lg shadow-xl border z-40 max-h-[85vh] overflow-y-auto p-4 custom-scrollbar">
                                <div className="flex justify-between items-center mb-4"><h3 className="text-xs font-bold uppercase text-gray-400">Propriedades</h3><button onClick={() => setSelectedId(null)}><X className="w-4 h-4"/></button></div>
                                {getActiveElements().find(e => e.id === selectedId) && (
                                    <div className="space-y-4">
                                        <div><label className="text-[10px] font-bold text-gray-500 uppercase">Nome</label><input type="text" value={getActiveElements().find(e => e.id === selectedId)?.name} onChange={(e) => updateElementName(selectedId, e.target.value)} className="w-full text-xs p-2 border rounded" /></div>
                                        {getActiveElements().find(e => e.id === selectedId)?.type === 'table' && (
                                            <div className="space-y-3 pt-3 border-t">
                                                <h4 className="text-[10px] font-bold text-indigo-600 uppercase">Tabela</h4>
                                                <div><label className="text-[10px] text-gray-500 uppercase">Linhas</label><input type="range" min="1" max="50" value={getActiveElements().find(e => e.id === selectedId)?.style.table?.rows} onChange={(e) => updateTableConfig(selectedId, { rows: parseInt(e.target.value) })} className="w-full" /></div>
                                                {/* NOVO CONTROLE DE ALTURA DA LINHA */}
                                                <div><label className="text-[10px] text-gray-500 uppercase">Altura da Linha ({getActiveElements().find(e => e.id === selectedId)?.style.table?.rowHeight}px)</label><input type="range" min="10" max="200" value={getActiveElements().find(e => e.id === selectedId)?.style.table?.rowHeight || 30} onChange={(e) => updateTableConfig(selectedId, { rowHeight: parseInt(e.target.value) })} className="w-full" /></div>
                                                <div className="grid grid-cols-2 gap-2">
                                                    <div><label className="text-[10px] text-gray-500 uppercase">Borda</label><input type="number" value={getActiveElements().find(e => e.id === selectedId)?.style.table?.borderWidth} onChange={(e) => updateTableConfig(selectedId, { borderWidth: parseFloat(e.target.value) })} className="w-full text-xs p-1 border rounded" /></div>
                                                    <div><label className="text-[10px] text-gray-500 uppercase">Cor</label><input type="color" value={getActiveElements().find(e => e.id === selectedId)?.style.table?.borderColor} onChange={(e) => updateTableConfig(selectedId, { borderColor: e.target.value })} className="w-full h-8" /></div>
                                                </div>
                                            </div>
                                        )}
                                        {renderTypographyControls(getActiveElements().find(e => e.id === selectedId)?.style as TextStyleConfig, (u) => updateElementStyle(selectedId, u))}
                                        <button onClick={() => removeElement(selectedId)} className="w-full py-2 bg-red-50 text-red-600 text-xs font-bold rounded">Excluir</button>
                                    </div>
                                )}
                            </div>
                        )}
                        <div className="flex-1 w-full flex items-center justify-center overflow-auto custom-scrollbar">{renderEditorPage()}</div>
                    </div>
                )}
                {activeTab === 'preview' && (
                    <div className="flex-1 w-full overflow-y-auto p-8 bg-gray-500 custom-scrollbar">
                        <div className="max-w-6xl mx-auto flex flex-wrap justify-center gap-8">{renderPrintLayout(renderedPreviewCount)}</div>
                    </div>
                )}
            </main>
          </div>
      </div>
    </div>
  );
};

import React, { useRef, memo } from 'react';
import { LayoutElement, DayData, TextStyleConfig } from '../../../types';
import { getMonthName, getDayName, generateMonthGrid, checkIsHoliday } from '../../../core/backend/calendar';

interface ElementRendererProps {
  element: LayoutElement;
  dayData: DayData;
  quote?: string;
  isEditor: boolean;
  isSelected?: boolean;
  onContentChange?: (id: string, content: string) => void;
  onTableResizeStart?: (e: React.MouseEvent, elementId: string, colIndex: number) => void;
  onTableCellChange?: (elementId: string, row: number, col: number, text: string) => void;
  onTableCellFocus?: (elementId: string, row: number, col: number) => void;
}

const TableCell = memo(({ 
    r, c, content, isEditor, isHeaderCell, isLastCol, style, elementId,
    onTableCellChange, onTableCellFocus, onTableResizeStart
}: {
    r: number, c: number, content: string, isEditor: boolean, isHeaderCell: boolean, isLastCol: boolean,
    style: React.CSSProperties, elementId: string,
    onTableCellChange?: (id: string, r: number, c: number, v: string) => void,
    onTableCellFocus?: (id: string, r: number, c: number) => void,
    onTableResizeStart?: (e: React.MouseEvent, id: string, c: number) => void
}) => {
    const inputRef = useRef<HTMLTextAreaElement>(null);
    return (
        <div className="relative flex-shrink-0" style={style} onClick={() => isEditor && inputRef.current?.focus()}>
            {isEditor ? (
                <textarea 
                    ref={inputRef} value={content}
                    onChange={(e) => onTableCellChange?.(elementId, r, c, e.target.value)}
                    onFocus={() => onTableCellFocus?.(elementId, r, c)}
                    className="w-full bg-transparent border-none resize-none p-1 focus:ring-1 focus:ring-indigo-300 leading-tight block h-full overflow-hidden"
                    style={{ fontFamily: 'inherit', fontSize: 'inherit', fontWeight: 'inherit', color: 'inherit', textAlign: 'inherit' }}
                    onMouseDown={(e) => e.stopPropagation()} 
                />
            ) : ( <div className="w-full p-1 whitespace-pre-wrap leading-tight h-full">{content}</div> )}
            {isEditor && !isLastCol && (
                <div className="absolute top-0 right-[-3px] h-full w-[6px] cursor-col-resize hover:bg-indigo-400 opacity-0 hover:opacity-50 z-20 transition-opacity" onMouseDown={(e) => onTableResizeStart?.(e, elementId, c)} />
            )}
        </div>
