});

export const ElementRenderer: React.FC<ElementRendererProps> = memo(({ 
    element, dayData, quote, isEditor, isSelected,
    onContentChange, onTableResizeStart, onTableCellChange, onTableCellFocus
}) => {
  const d = dayData;
  const style = element.style;

  const renderMoonIcon = (phase: string, color: string) => {
      const p = phase.toLowerCase();
      if (p.includes('nova')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
      if (p.includes('cheia')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><circle cx="12" cy="12" r="10"/></svg>;
      return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
  }

  const renderSingleMonth = (monthIndex: number, year: number) => {
      const grid = generateMonthGrid(year, monthIndex);
      const titleStyle = style.fullCalendar?.title || { fontSize: 12, fontFamily: 'Inter', fontWeight: 'bold', color: '#000', textAlign: 'center', textTransform: 'uppercase', letterSpacing: 0 } as TextStyleConfig;
      const weekStyle = style.fullCalendar?.weekDays || { fontSize: 8, fontFamily: 'Inter', fontWeight: 'bold', color: '#666', textAlign: 'center', textTransform: 'none', letterSpacing: 0 } as TextStyleConfig;
      const dayStyle = style.fullCalendar?.days || { fontSize: 10, fontFamily: 'Inter', fontWeight: 'normal', color: '#333', textAlign: 'center', textTransform: 'none', letterSpacing: 0 } as TextStyleConfig;
      const gridConfig = style.fullCalendar?.grid || { borderColor: '#ddd', borderWidth: 1, cellBackgroundColor: 'transparent', headerBackgroundColor: 'transparent', borders: { top: false, bottom: false, left: false, right: false, insideHorizontal: false, insideVertical: false, headerSeparator: false } };
      const specialDaysConfig = style.fullCalendar?.specialDays || { highlightSundays: false, highlightHolidays: false, style: { color: '#ff0000', fontWeight: 'bold', fontSize: 10, fontFamily: 'Inter', textAlign: 'center', textTransform: 'none', letterSpacing: 0 } };
      const baseBorderStyle = `${gridConfig.borderWidth}px solid ${gridConfig.borderColor}`;
      return (
          <div key={monthIndex} className="flex flex-col w-full h-full">
              <div className="mb-1 pb-0.5" style={{ fontSize: titleStyle.fontSize, fontFamily: titleStyle.fontFamily, fontWeight: titleStyle.fontWeight, color: titleStyle.color, textAlign: titleStyle.textAlign }}>{getMonthName(monthIndex)}</div>
              <div className="grid grid-cols-7 gap-0 flex-1">
                  {['D','S','T','Q','Q','S','S'].map((wd, ci) => (
                      <div key={ci} style={{ fontSize: weekStyle.fontSize, fontFamily: weekStyle.fontFamily, fontWeight: weekStyle.fontWeight, color: weekStyle.color, backgroundColor: gridConfig.headerBackgroundColor, borderBottom: gridConfig.borders?.headerSeparator ? baseBorderStyle : 'none' }}>{wd}</div>
                  ))}
                  {grid.flat().map((dayNum, i) => {
                      const isSun = i % 7 === 0;
                      const activeStyle = isSun && specialDaysConfig.highlightSundays ? specialDaysConfig.style : dayStyle;
                      return <div key={i} style={{ fontSize: activeStyle.fontSize, color: activeStyle.color, backgroundColor: dayNum ? gridConfig.cellBackgroundColor : 'transparent' }}>{dayNum || ''}</div>;
                  })}
              </div>
          </div>
      );
  };

  switch (element.type) {
    case 'day_number': return <div style={{...style, display: 'block', width: '100%'}}>{d.dayOfMonth}</div>;
    case 'month_name': return <div style={{...style, display: 'block', width: '100%'}}>{getMonthName(d.month)}</div>;
    case 'day_name': return <div style={{...style, display: 'block', width: '100%'}}>{getDayName(d.dayOfWeek)}</div>;
    case 'year': return <div style={{...style, display: 'block', width: '100%'}}>{d.year}</div>;
    case 'text': 
        if (isEditor && isSelected) {
            return <textarea value={element.content || ''} onChange={(e) => onContentChange?.(element.id, e.target.value)} style={{...style, width: '100%', height: '100%', resize: 'none', background: 'rgba(255,255,255,0.5)', outline: 'none'}} autoFocus onMouseDown={(e) => e.stopPropagation()} />;
        }
        return <div style={{...style, display: 'block', width: '100%', whiteSpace: 'pre-wrap'}}>{element.content || (isEditor ? 'Texto' : '')}</div>;
    case 'vector_flower': return <svg viewBox="0 0 24 24" className="w-full h-full"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" fill={style.backgroundColor} stroke={style.color} /></svg>;
    case 'lines': 
        const lineCount = Math.floor((element.h / 100 * (isEditor ? 600 : 800)) / (style.lineSpacing || 24)); 
        return <>{Array(Math.max(1, lineCount)).fill(0).map((_, i) => (<div key={i} className="w-full border-b" style={{ height: style.lineSpacing, borderColor: style.color }}></div>))}</>;
    case 'box': return <div className="w-full h-full" style={{ backgroundColor: style.backgroundColor, border: `${style.borderWidth}px solid ${style.borderColor}`, borderRadius: style.borderRadius }}></div>;
    case 'circle': return <div className="w-full h-full rounded-full" style={{ backgroundColor: style.backgroundColor, border: `${style.borderWidth}px solid ${style.borderColor}` }}></div>;
    case 'mini_calendar': return <div className="w-full h-full flex flex-col">{renderSingleMonth(d.month + (style.calendarOffset || 0), d.year)}</div>;
    case 'table':
        const rows = style.table?.rows || 10;
        const columns = style.table?.cols || 2;
        const colWs = style.table?.columnWidths || Array(columns).fill(100 / columns);
        const gStyle = style.table?.textStyle || { fontFamily: 'Inter', fontSize: 10, fontWeight: 'normal', color: '#666', textAlign: 'left' };
        const borderColor = style.table?.borderColor || '#000';
        const borderWidth = style.table?.borderWidth ?? 1;
        const bStyle = `${borderWidth}px solid ${borderColor}`;

        // Se rowHeight for definido, usamos ele fixamente. Caso contrário, usamos flex-1.
        const rowHeightPx = style.table?.rowHeight;
        const rowWrapperStyle = rowHeightPx ? { height: `${rowHeightPx}px`, flex: 'none' } : { flex: '1 1 0%' };

        return (
            <div className="w-full h-full flex flex-col overflow-auto custom-scrollbar">
                {Array(rows).fill(0).map((_, r) => (
                    <div key={r} className="flex w-full relative" style={rowWrapperStyle}>
                        {Array(columns).fill(0).map((_, c) => {
                            const isH = style.table?.headerRow && r === 0;
                            const tS = { ...gStyle, ...(style.table?.rowStyles?.[r] || {}), ...(style.table?.colStyles?.[c] || {}) };
                            const cellStyle: React.CSSProperties = {
                                width: `${colWs[c]}%`, height: '100%',
                                borderBottom: bStyle, borderRight: c === columns - 1 ? (style.table?.borders?.right ? bStyle : 'none') : bStyle,
                                borderLeft: c === 0 && style.table?.borders?.left ? bStyle : 'none',
                                borderTop: r === 0 && style.table?.borders?.top ? bStyle : 'none',
                                backgroundColor: isH ? '#f3f4f6' : (tS.backgroundColor || 'transparent'),
                                display: 'flex', flexDirection: 'column', justifyContent: 'center',
                                fontFamily: tS.fontFamily, fontSize: tS.fontSize, color: tS.color, textAlign: tS.textAlign as any
                            };
                            return (
                                <TableCell 
                                    key={c} r={r} c={c} elementId={element.id} content={style.table?.cellContent?.[`${r}-${c}`] || ''}
                                    isEditor={isEditor} isHeaderCell={isH} isLastCol={c === columns - 1} style={cellStyle}
                                    onTableCellChange={onTableCellChange} onTableCellFocus={onTableCellFocus} onTableResizeStart={onTableResizeStart}
                                />
                            );
                        })}
                    </div>
                ))}
            </div>
        );
    default: return null;
  }
});

import { jsPDF } from "jspdf";
import { AgendaConfig, DayData, LayoutElement } from "../types";
import { getMonthName, getDayName } from "../core/backend/calendar";

const hexToRgb = (hex: string): { r: number, g: number, b: number } | null => {
  if (!hex || hex === 'transparent') return null;
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) } : null;
};

const renderElementToPDF = (doc: jsPDF, el: LayoutElement, day: DayData | null, quote: string | undefined, pageW: number, pageH: number) => {
    const { x, y, w, h, style } = el;
    const absX = (x / 100) * pageW;
    const absY = (y / 100) * pageH;
    const absW = (w / 100) * pageW;
    const absH = (h / 100) * pageH;
    const rgb = hexToRgb(style.color || '#000000') || { r: 0, g: 0, b: 0 };
    doc.setTextColor(rgb.r, rgb.g, rgb.b);
    doc.setFontSize(style.fontSize || 12); 

    let text = '';
    if (el.type === 'text') text = el.content || '';
    if (el.type === 'day_number' && day) text = day.dayOfMonth.toString();
    if (el.type === 'day_name' && day) text = getDayName(day.dayOfWeek);
    if (el.type === 'month_name' && day) text = getMonthName(day.month);
    if (el.type === 'year' && day) text = day.year.toString();

    if (style.backgroundColor && style.backgroundColor !== 'transparent') {
        const bg = hexToRgb(style.backgroundColor);
        if (bg) { doc.setFillColor(bg.r, bg.g, bg.b); doc.rect(absX, absY, absW, absH, 'F'); }
    }

    if (el.type === 'table') {
        const rows = style.table?.rows || 1;
        const cols = style.table?.cols || 1;
        const rowHeightMm = style.table?.rowHeight ? (style.table.rowHeight * 0.264583) : (absH / rows);
        const colWs = style.table?.columnWidths || Array(cols).fill(100/cols);
        let curY = absY;
        for (let r=0; r<rows; r++) {
            let curX = absX;
            for (let c=0; c<cols; c++) {
                const cw = (colWs[c] / 100) * absW;
                doc.setDrawColor(200, 200, 200);
                doc.rect(curX, curY, cw, rowHeightMm);
                const content = style.table?.cellContent?.[`${r}-${c}`];
                if (content) { doc.setFontSize(style.table?.textStyle?.fontSize || 8); doc.text(content, curX + 1, curY + (rowHeightMm/2) + 1); }
                curX += cw;
            }
            curY += rowHeightMm;
        }
    } else if (text) {
        doc.text(text, absX, absY + (style.fontSize || 12) * 0.35);
    }
};

export const generateAndDownloadPDF = async (config: AgendaConfig, generatedDays: DayData[], quotes: string[], onProgress: (progress: number) => void) => {
    const format = config.pageSize.toLowerCase();
    const orientation = config.orientation === 'portrait' ? 'p' : 'l';
    const doc = new jsPDF({ orientation, unit: "mm", format, compress: true });
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    let count = 0;
    const total = config.introPages.length + generatedDays.length;
    for (const page of config.introPages) {
        if (count > 0) doc.addPage(format, orientation);
        count++; page.elements.forEach(el => renderElementToPDF(doc, el, null, undefined, pageW, pageH));
        onProgress(Math.round((count / total) * 100));
    }
    for (const day of generatedDays) {
        doc.addPage(format, orientation);
        count++; config.elements.forEach(el => renderElementToPDF(doc, el, day, quotes[day.month], pageW, pageH));
        if (count % 20 === 0) { onProgress(Math.round((count / total) * 100)); await new Promise(r => setTimeout(r, 0)); }
    }
    doc.save(`Agenda_${config.year}.pdf`);
};

