import React, { useRef, memo } from 'react';
import { LayoutElement, DayData, TextStyleConfig } from '../../../types';
import { getMonthName, getDayName, generateMonthGrid, checkIsHoliday } from '../../../core/backend/calendar';
import { Moon, Square, Circle, Flower, Star, Heart, Leaf } from 'lucide-react';

interface ElementRendererProps {
  element: LayoutElement;
  dayData: DayData;
  quote?: string;
  isEditor: boolean;
  isSelected?: boolean;
  onContentChange?: (id: string, content: string) => void;
  onTableResizeStart?: (e: React.MouseEvent, elementId: string, colIndex: number) => void;
  onTableCellChange?: (elementId: string, row: number, col: number, text: string) => void;
  onTableCellFocus?: (elementId: string, row: number, col: number) => void;
}

const TableCell = memo(({ r, c, content, isEditor, isHeaderCell, isLastCol, style, elementId, onTableCellChange, onTableCellFocus, onTableResizeStart }: any) => {
    const inputRef = useRef<HTMLTextAreaElement>(null);
    return (
        <div className="relative flex-shrink-0" style={style} onClick={() => isEditor && inputRef.current?.focus()}>
            {isEditor ? (
                <textarea ref={inputRef} value={content} onChange={(e) => onTableCellChange && onTableCellChange(elementId, r, c, e.target.value)} onFocus={() => onTableCellFocus && onTableCellFocus(elementId, r, c)} className="w-full bg-transparent border-none resize-none p-1 focus:ring-1 focus:ring-indigo-300 focus:bg-white/50 leading-tight block" style={{ fontFamily: 'inherit', fontSize: 'inherit', fontWeight: 'inherit', color: 'inherit', textAlign: 'inherit', height: '100%', overflow: 'hidden' }} onMouseDown={(e) => e.stopPropagation()} />
            ) : (<div className="w-full p-1 whitespace-pre-wrap leading-tight h-full">{content}</div>)}
            {isEditor && !isLastCol && (<div className="absolute top-0 right-[-3px] h-full w-[6px] cursor-col-resize hover:bg-indigo-400 opacity-0 hover:opacity-50 z-20 transition-opacity" onMouseDown={(e) => onTableResizeStart && onTableResizeStart(e, elementId, c)} />)}
        </div>
    );
});

export const ElementRenderer: React.FC<ElementRendererProps> = memo(({ element, dayData, quote, isEditor, isSelected, onContentChange, onTableResizeStart, onTableCellChange, onTableCellFocus }) => {
  const d = dayData;
  const style = element.style;

  const getBackgroundStyle = () => {
      if (element.type === 'box' && style.backgroundType === 'gradient' && style.gradientColors) {
          const deg = style.gradientDirection !== undefined ? style.gradientDirection : 180;
          return `linear-gradient(${deg}deg, ${style.gradientColors[0]}, ${style.gradientColors[1]})`;
      }
      return style.backgroundColor || 'transparent';
  };

  const getBoxShadow = () => {
      if (!style.boxShadow || style.boxShadow === 'none') return 'none';
      if (style.boxShadow === 'sm') return '0 1px 2px 0 rgb(0 0 0 / 0.05)';
      if (style.boxShadow === 'md') return '0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1)';
      if (style.boxShadow === 'lg') return '0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)';
      return 'none';
  };

  const renderMoonIcon = (phase: string, color: string) => {
      const p = phase.toLowerCase();
      if (p.includes('nova')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
      if (p.includes('cheia')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><circle cx="12" cy="12" r="10"/></svg>;
      if (p.includes('crescente')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><path d="M12 3a9 9 0 1 0 0 18 7 7 0 0 1 0-14 7 7 0 0 1 0-4z" /></svg>;
      if (p.includes('minguante')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><path d="M12 3a7 7 0 0 0 0 14 7 7 0 0 0 0 4 9 9 0 1 1 0-18z" /></svg>;
      return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
  }

  const renderVector = () => {
      const variant = style.variant || 'flower_1';
      let path = "M12 2C9.5 2 8 4 8 6C8 4 6.5 2 4 2C1.5 2 0 4.5 0 7.5C0 10.5 3 14 12 22C21 14 24 10.5 24 7.5C24 4.5 22.5 2 20 2C17.5 2 16 4 16 6C16 4 14.5 2 12 2Z";
      if (variant === 'star') path = "M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z";
      else if (variant === 'heart') path = "M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z";
      else if (variant === 'leaf') path = "M17 8C8 10 5.9 16.17 3.82 21.34 9.17 19.8 15 17 17 8zm-7.05 5.55A3.99 3.99 0 0 0 12 13a4 4 0 0 0 0 8C9.5 16.5 9.5 16 9.95 13.55zM12 2C9.5 2 8 4 8 6c0 4 6 7 4 7s4-3 4-7c0-2-1.5-4-4-4z";
      return <svg viewBox="0 0 24 24" className="w-full h-full" style={{ overflow: 'visible' }}><path d={path} fill={style.backgroundColor || 'transparent'} stroke={style.color || 'none'} strokeWidth="1.5" strokeLinejoin="round"/></svg>; 
  }

  const renderSingleMonth = (monthIndex: number, year: number) => {
      const grid = generateMonthGrid(year, monthIndex);
      const titleStyle = style.fullCalendar?.title || { fontSize: 12, fontFamily: 'Inter', fontWeight: 'bold', color: '#000', textAlign: 'center', textTransform: 'uppercase', letterSpacing: 0 } as TextStyleConfig;
      const weekStyle = style.fullCalendar?.weekDays || { fontSize: 8, fontFamily: 'Inter', fontWeight: 'bold', color: '#666', textAlign: 'center', textTransform: 'none', letterSpacing: 0 } as TextStyleConfig;
      const dayStyle = style.fullCalendar?.days || { fontSize: 10, fontFamily: 'Inter', fontWeight: 'normal', color: '#333', textAlign: 'center', textTransform: 'none', letterSpacing: 0 } as TextStyleConfig;
      const gridConfig = style.fullCalendar?.grid || { borderColor: '#ddd', borderWidth: 1, cellBackgroundColor: 'transparent', headerBackgroundColor: 'transparent', borders: { top: false, bottom: false, left: false, right: false, insideHorizontal: false, insideVertical: false, headerSeparator: false } };
      const specialDaysConfig = style.fullCalendar?.specialDays || { highlightSundays: false, highlightHolidays: false, style: { color: '#ff0000', fontWeight: 'bold', fontSize: 10, fontFamily: 'Inter', textAlign: 'center', textTransform: 'none', letterSpacing: 0 } };
      const baseBorderStyle = `${gridConfig.borderWidth}px solid ${gridConfig.borderColor}`;
      const noBorder = 'none';
      const flatGrid = grid.flat();
      const totalRows = grid.length + 1; 
      const titleText = element.type === 'mini_calendar' ? getMonthName(monthIndex) : `${getMonthName(monthIndex)} ${year}`;

      return (
          <div key={monthIndex} className="flex flex-col w-full h-full">
              <div className="mb-1 pb-0.5" style={{ fontSize: titleStyle.fontSize, fontFamily: titleStyle.fontFamily, fontWeight: titleStyle.fontWeight, color: titleStyle.color, textAlign: titleStyle.textAlign, textTransform: titleStyle.textTransform, letterSpacing: `${titleStyle.letterSpacing}px` }}>{titleText}</div>
              <div className="grid grid-cols-7 gap-0 flex-1">
                  {['D','S','T','Q','Q','S','S'].map((wd, colIndex) => (<div key={`h-${colIndex}`} className="flex items-center justify-center" style={{ fontSize: weekStyle.fontSize, fontFamily: weekStyle.fontFamily, fontWeight: weekStyle.fontWeight, color: weekStyle.color, textTransform: weekStyle.textTransform, letterSpacing: `${weekStyle.letterSpacing}px`, backgroundColor: gridConfig.headerBackgroundColor, borderTop: gridConfig.borders?.top ? baseBorderStyle : noBorder, borderBottom: gridConfig.borders?.headerSeparator ? baseBorderStyle : (gridConfig.borders?.insideHorizontal ? baseBorderStyle : noBorder), borderLeft: (colIndex === 0 && gridConfig.borders?.left) ? baseBorderStyle : (colIndex > 0 && gridConfig.borders?.insideVertical ? baseBorderStyle : noBorder), borderRight: (colIndex === 6 && gridConfig.borders?.right) ? baseBorderStyle : noBorder }}>{wd}</div>))}
                  {flatGrid.map((dayNum, i) => {
                      const colIndex = i % 7;
                      const rowIndex = Math.floor(i / 7) + 1; 
                      const isLastRow = rowIndex === totalRows - 1;
                      const isSunday = colIndex === 0;
                      const isHoliday = dayNum ? !!checkIsHoliday(year, monthIndex, dayNum) : false;
                      const isSpecial = (isSunday && specialDaysConfig.highlightSundays) || (isHoliday && specialDaysConfig.highlightHolidays);
                      const isCurrentDayPage = element.type === 'mini_calendar' && style.calendarOffset === 0 && dayNum === d.dayOfMonth;
                      const activeStyle = isSpecial ? specialDaysConfig.style : dayStyle;
                      return (<div key={`d-${i}`} className={`flex items-center justify-center ${isCurrentDayPage ? 'bg-indigo-600 text-white rounded-sm font-bold' : ''}`} style={{ fontSize: activeStyle.fontSize, fontFamily: activeStyle.fontFamily, fontWeight: isCurrentDayPage ? 'bold' : activeStyle.fontWeight, color: isCurrentDayPage ? '#ffffff' : activeStyle.color, letterSpacing: `${activeStyle.letterSpacing}px`, backgroundColor: isCurrentDayPage ? undefined : (isSpecial && activeStyle.backgroundColor ? activeStyle.backgroundColor : (dayNum ? gridConfig.cellBackgroundColor : 'transparent')), borderBottom: isLastRow ? (gridConfig.borders?.bottom ? baseBorderStyle : noBorder) : (gridConfig.borders?.insideHorizontal ? baseBorderStyle : noBorder), borderLeft: (colIndex === 0 && gridConfig.borders?.left) ? baseBorderStyle : (colIndex > 0 && gridConfig.borders?.insideVertical ? baseBorderStyle : noBorder), borderRight: (colIndex === 6 && gridConfig.borders?.right) ? baseBorderStyle : noBorder }}>{dayNum || ''}</div>);
                  })}
              </div>
          </div>
      );
  };

  switch (element.type) {
    case 'day_number': return <div style={{...style, display: 'block', width: '100%'}}>{d.dayOfMonth}</div>;
    case 'month_name': return <div style={{...style, display: 'block', width: '100%'}}>{getMonthName(d.month)}</div>;
    case 'day_name': return <div style={{...style, display: 'block', width: '100%'}}>{getDayName(d.dayOfWeek)}</div>;
    case 'year': return <div style={{...style, display: 'block', width: '100%'}}>{d.year}</div>;
    case 'holiday': return <div style={{...style, display: 'block', width: '100%'}}>{d.holiday || (isEditor ? 'Nome do Feriado' : '')}</div>;
    case 'text': 
        if (isEditor && isSelected) {
            return <textarea value={element.content || ''} onChange={(e) => onContentChange && onContentChange(element.id, e.target.value)} style={{...style, width: '100%', height: '100%', resize: 'none', background: 'rgba(255,255,255,0.5)', border: '1px dashed #ccc', outline: 'none', display: 'block', whiteSpace: 'pre-wrap', overflow: 'hidden'}} autoFocus onMouseDown={(e) => e.stopPropagation()} />;
        }
        return <div style={{...style, display: 'block', width: '100%', whiteSpace: 'pre-wrap'}}>{element.content || (isEditor ? 'Texto Livre' : '')}</div>;
    case 'quote': return <div style={{...style, display: 'block', width: '100%'}}>{quote || (isEditor ? '"Frase Inspiradora"' : '')}</div>;
    case 'vector_flower': return renderVector();
    case 'moon': 
        const phase = d.moonPhase || (isEditor ? 'Lua cheia' : '');
        if (phase) {
            const variant = style.variant || 'full_info';
            if (variant === 'icon_only') return <div className="w-full h-full flex items-center justify-center">{renderMoonIcon(phase, style.color || '#000')}</div>;
            return <div className="flex items-center gap-1.5 h-full"><div className="shrink-0" style={{ width: style.fontSize, height: style.fontSize }}>{renderMoonIcon(phase, style.color || '#000')}</div><span className="whitespace-nowrap" style={{ fontSize: style.fontSize, fontFamily: style.fontFamily, color: style.color }}>{phase}</span></div>;
        }
        return null;
    case 'lines': 
        const isSingleLine = element.h < 3 || (style.lineSpacing && element.h * (isEditor ? 6 : 8) <= style.lineSpacing);
        const borderStyleVal = style.borderStyle || 'solid';
        const borderWidthVal = style.borderWidth !== undefined ? style.borderWidth : 1;
        if (isSingleLine) return <div className="w-full h-full flex items-center justify-center"><div className="w-full" style={{ borderTopWidth: `${borderWidthVal}px`, borderTopStyle: borderStyleVal, borderTopColor: style.color }}></div></div>;
        const lineCount = Math.floor((element.h / 100 * (isEditor ? 600 : 800)) / (style.lineSpacing || 24)); 
        const lineStyle: React.CSSProperties = { height: style.lineSpacing, borderColor: style.color, borderBottomStyle: borderStyleVal, borderBottomWidth: `${borderWidthVal}px` };
        return <>{Array(Math.max(1, lineCount)).fill(0).map((_, i) => (<div key={i} className="w-full relative" style={lineStyle}>{style.showTimes && <span className="absolute -top-2 left-0 text-[10px] font-mono text-gray-500 bg-white/50 pr-1" style={{ fontSize: (style.fontSize ? style.fontSize * 0.7 : 10) }}>{String((style.startHour || 7) + i).padStart(2, '0')}:00</span>}</div>))}</>;

    case 'box': 
        return (
            <div className="w-full h-full" style={{ 
                background: getBackgroundStyle(),
                border: `${style.borderWidth}px ${style.borderStyle || 'solid'} ${style.borderColor}`, 
                borderRadius: style.borderRadius,
                boxShadow: getBoxShadow(),
                opacity: style.opacity ?? 1
            }}></div>
        );
    case 'circle': return <div className="w-full h-full rounded-full" style={{ backgroundColor: style.backgroundColor, border: `${style.borderWidth}px ${style.borderStyle || 'solid'} ${style.borderColor}` }}></div>;
    case 'habit_tracker':
       const habitCount = Math.max(1, Math.floor((Math.max(0, (element.h / 100 * (isEditor ? 600 : 800)) - 20)) / 20));
       return <div className="w-full h-full flex flex-col" style={{ opacity: style.opacity }}><div className="text-[10px] text-gray-500 mb-1 font-bold tracking-wider uppercase">Hábitos</div><div className="flex-1 flex flex-col gap-1 overflow-hidden">{Array(habitCount).fill(0).map((_, i) => (<div key={i} className="flex items-center border-b border-gray-200 h-5 shrink-0"><div className="w-4 h-4 border border-gray-300 rounded mr-2"></div><div className="h-2 w-full bg-gray-100 rounded"></div></div>))}</div></div>;
    case 'note_grid': return <div className="w-full h-full" style={{ backgroundImage: `radial-gradient(${style.color || '#ccc'} 1px, transparent 1px)`, backgroundSize: '15px 15px', opacity: style.opacity }}></div>;
    case 'mini_calendar':
        let targetMonth = d.month + (style.calendarOffset || 0);
        let targetYear = d.year;
        if (targetMonth < 0) { targetMonth = 11; targetYear -= 1; } else if (targetMonth > 11) { targetMonth = 0; targetYear += 1; }
        return <div className="w-full h-full flex flex-col" style={{ backgroundColor: style.backgroundColor || 'transparent' }}>{renderSingleMonth(targetMonth, targetYear)}</div>;
    case 'full_calendar':
        const months = Array.from({ length: 12 }, (_, i) => i);
        const cols = style.monthsPerRow || 3;
        const gap = style.gap !== undefined ? style.gap : 10;
        return <div className="w-full h-full" style={{ display: 'grid', gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: `${gap}px`, backgroundColor: style.backgroundColor || 'transparent', padding: '4px' }}>{months.map(m => (<div key={m} className="overflow-hidden">{renderSingleMonth(m, d.year)}</div>))}</div>;
    case 'holiday_list':
        if (isEditor && isSelected) { return <textarea value={element.content || "Feriados Nacionais (Editável)"} onChange={(e) => onContentChange && onContentChange(element.id, e.target.value)} style={{ fontSize: style.fontSize, fontFamily: style.fontFamily, color: style.color, textAlign: style.textAlign, lineHeight: 1.5, width: '100%', height: '100%', resize: 'none', background: 'rgba(255,255,255,0.5)', border: '1px dashed #ccc', outline: 'none', whiteSpace: 'pre-wrap' }} autoFocus onMouseDown={(e) => e.stopPropagation()} />; }
        return <div className="w-full h-full whitespace-pre-wrap" style={{ fontSize: style.fontSize, fontFamily: style.fontFamily, color: style.color, textAlign: style.textAlign, lineHeight: 1.5 }}>{element.content || "Feriados Nacionais (Editável)"}</div>;
    case 'table':
        const rows = style.table?.rows || 10;
        const columns = style.table?.cols || 2;
        const hasHeader = style.table?.headerRow;
        const columnWidths = style.table?.columnWidths || Array(columns).fill(100 / columns);
        const globalTextStyle = style.table?.textStyle || { fontFamily: 'Inter', fontSize: 10, fontWeight: 'normal', color: '#666', textAlign: 'left', verticalAlign: 'top', textTransform: 'none', letterSpacing: 0, backgroundColor: 'transparent' };
        const rowStyles = style.table?.rowStyles || {};
        const colStyles = style.table?.colStyles || {};
        const borders = style.table?.borders || { top: true, bottom: true, left: true, right: true, insideHorizontal: true, insideVertical: true, headerSeparator: true };
        const borderColor = style.table?.borderColor || '#000';
        const borderWidth = style.table?.borderWidth ?? 1;
        const borderStyle = `${borderWidth}px solid ${borderColor}`;
        const noBorder2 = 'none'; // Renamed to avoid collision if any
        const baseRowHeight = style.table?.rowHeight ? `${style.table.rowHeight}px` : 'auto';
        return (
            <div className="w-full h-full flex flex-col" style={{ overflow: 'hidden' }}>
                {Array(rows).fill(0).map((_, r) => (
                    <div key={r} className="flex w-full flex-1 relative" style={{ minHeight: baseRowHeight }}>
                        {Array(columns).fill(0).map((_, c) => {
                            const isLastCol = c === columns - 1;
                            const isLastRow = r === rows - 1;
                            const cellKey = `${r}-${c}`;
                            const content = style.table?.cellContent?.[cellKey] || '';
                            const isHeaderCell = hasHeader && r === 0;
                            const tStyle = { ...globalTextStyle, ...(rowStyles[r] || {}), ...(colStyles[c] || {}) };
                            let justifyContent = 'flex-start';
                            if (tStyle.verticalAlign === 'middle') justifyContent = 'center';
                            if (tStyle.verticalAlign === 'bottom') justifyContent = 'flex-end';
                            const cellStyle: React.CSSProperties = { width: `${columnWidths[c]}%`, height: '100%', borderTop: (r === 0 && borders.top) ? borderStyle : noBorder2, borderBottom: isLastRow ? (borders.bottom ? borderStyle : noBorder2) : (isHeaderCell && borders.headerSeparator ? borderStyle : (borders.insideHorizontal ? borderStyle : noBorder2)), borderLeft: (c === 0 && borders.left) ? borderStyle : noBorder2, borderRight: isLastCol ? (borders.right ? borderStyle : noBorder2) : (borders.insideVertical ? borderStyle : noBorder2), backgroundColor: isHeaderCell ? '#f3f4f6' : (tStyle.backgroundColor || 'transparent'), display: 'flex', flexDirection: 'column', justifyContent: justifyContent, alignItems: 'stretch', fontFamily: tStyle.fontFamily, fontSize: tStyle.fontSize, fontWeight: isHeaderCell ? 'bold' : tStyle.fontWeight, color: tStyle.color, textAlign: tStyle.textAlign as any, textTransform: tStyle.textTransform as any, letterSpacing: `${tStyle.letterSpacing}px` };
                            return <TableCell key={c} r={r} c={c} elementId={element.id} content={content} isEditor={isEditor} isHeaderCell={isHeaderCell} isLastCol={isLastCol} style={cellStyle} onTableCellChange={onTableCellChange} onTableCellFocus={onTableCellFocus} onTableResizeStart={onTableResizeStart} />;
                        })}
                    </div>
                ))}
            </div>
        );
    default: return null;
  }
});

import { jsPDF } from "jspdf";
import { AgendaConfig, DayData, LayoutElement } from "../types";
import { getMonthName, getDayName } from "../core/backend/calendar";

const hexToRgb = (hex: string): { r: number, g: number, b: number } | null => {
  if (!hex || hex === 'transparent') return null;
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) } : null;
};

const getFont = (fontName: string | undefined, weight: string | number | undefined) => {
    let style = 'normal';
    if (weight === 'bold' || (typeof weight === 'number' && weight > 600)) style = 'bold';
    if (fontName?.includes('Playfair') || fontName?.includes('Merriweather')) return { font: 'times', style };
    if (fontName?.includes('Courier') || fontName?.includes('Mono')) return { font: 'courier', style };
    return { font: 'helvetica', style };
};

const renderElementToPDF = (doc: jsPDF, el: LayoutElement, day: DayData | null, quote: string | undefined, safeAreaW: number, safeAreaH: number, offsetX: number, offsetY: number) => {
    const { x, y, w, h, style } = el;
    const absX = (x / 100) * safeAreaW + offsetX;
    const absY = (y / 100) * safeAreaH + offsetY;
    const absW = (w / 100) * safeAreaW;
    const absH = (h / 100) * safeAreaH;

    const rgb = hexToRgb(style.color || '#000000') || { r: 0, g: 0, b: 0 };

    // Gradient Handling: Fallback to the first color for PDF stability
    let bgRgb = style.backgroundColor ? hexToRgb(style.backgroundColor) : null;
    if (el.type === 'box' && style.backgroundType === 'gradient' && style.gradientColors && style.gradientColors[0]) {
        bgRgb = hexToRgb(style.gradientColors[0]);
    }

    const fontConfig = getFont(style.fontFamily, style.fontWeight);
    doc.setTextColor(rgb.r, rgb.g, rgb.b);
    doc.setFont(fontConfig.font, fontConfig.style);
    doc.setFontSize(style.fontSize || 12); 

    let text = '';
    if (el.type === 'text') text = el.content || 'Texto';
    if (el.type === 'day_number' && day) text = day.dayOfMonth.toString();
    if (el.type === 'day_name' && day) text = getDayName(day.dayOfWeek);
    if (el.type === 'month_name' && day) text = getMonthName(day.month);
    if (el.type === 'year' && day) text = day.year.toString();
    if (el.type === 'quote') text = quote || '';
    if (el.type === 'holiday' && day) text = day.holiday || '';
    if (el.type === 'holiday_list') text = el.content || '';

    // --- RENDER LOGIC ---

    // Box/Circle Special Rendering (Shadows & Fills)
    if (el.type === 'box' || el.type === 'circle') {

        // 1. Draw Shadow (Simulated)
        if (style.boxShadow && style.boxShadow !== 'none') {
            const shadowOffset = style.boxShadow === 'sm' ? 0.5 : style.boxShadow === 'md' ? 1.0 : 2.0; // mm
            const shadowColor = { r: 200, g: 200, b: 200 };
            doc.setFillColor(shadowColor.r, shadowColor.g, shadowColor.b);

            // Draw shadow rect/circle offset
            if (el.type === 'circle') {
                const r = Math.min(absW, absH) / 2;
                doc.circle(absX + absW/2 + shadowOffset, absY + absH/2 + shadowOffset, r, 'F');
            } else {
                if (style.borderRadius && style.borderRadius > 0) {
                    const r = style.borderRadius * 0.264583; // px to mm approx
                    doc.roundedRect(absX + shadowOffset, absY + shadowOffset, absW, absH, r, r, 'F');
                } else {
                    doc.rect(absX + shadowOffset, absY + shadowOffset, absW, absH, 'F');
                }
            }
        }

        // 2. Draw Background Fill
        let paintOp = '';
        if (bgRgb) {
            doc.setFillColor(bgRgb.r, bgRgb.g, bgRgb.b);
            paintOp += 'F';
        }

        // 3. Draw Borders
        if (style.borderWidth && style.borderWidth > 0) {
            const borderColor = style.borderColor ? hexToRgb(style.borderColor) : rgb;
            if (borderColor) doc.setDrawColor(borderColor.r, borderColor.g, borderColor.b);
            doc.setLineWidth(style.borderWidth * 0.2); // Scale px to mm roughly

            if (style.borderStyle === 'dashed') doc.setLineDash([3, 3], 0);
            else if (style.borderStyle === 'dotted') doc.setLineDash([1, 1], 0);
            else doc.setLineDash([], 0);

            paintOp += 'D';
        }

        if (paintOp) {
            if (el.type === 'circle') {
                const r = Math.min(absW, absH) / 2;
                doc.circle(absX + absW/2, absY + absH/2, r, paintOp);
            } else {
                if (style.borderRadius && style.borderRadius > 0) {
                    const r = style.borderRadius * 0.264583; 
                    doc.roundedRect(absX, absY, absW, absH, r, r, paintOp);
                } else {
                    doc.rect(absX, absY, absW, absH, paintOp);
                }
            }
            // Reset dash
            doc.setLineDash([], 0);
        }
    }

    // Other element line drawing (lines, etc)
    else if ((style.borderWidth && style.borderWidth > 0) || el.type === 'lines') {
        const borderColor = (style.borderColor ? hexToRgb(style.borderColor) : null) || rgb;
        doc.setDrawColor(borderColor.r, borderColor.g, borderColor.b);
        doc.setLineWidth(style.borderWidth ? style.borderWidth * 0.2 : 0.1);

        if (el.type === 'lines') {
            const lineSpacingMm = style.lineSpacing ? (style.lineSpacing / 3.78) : 6;
            const numLines = Math.floor(absH / lineSpacingMm);
            for(let i=1; i<=numLines; i++) {
                const ly = absY + (i * lineSpacingMm);
                doc.line(absX, ly, absX + absW, ly);
                if (style.showTimes) {
                    doc.setFontSize(8);
                    const hour = (style.startHour || 7) + (i - 1);
                    doc.text(`${hour}:00`, absX - 2, ly - 1, { align: 'right' });
                }
            }
        }
    }

    // Text Rendering
    if (text) {
        const fontSize = style.fontSize || 12;
        let tx = absX;
        let align: 'left' | 'center' | 'right' = 'left';

        if (style.textAlign === 'center') { tx = absX + (absW / 2); align = 'center'; } 
        else if (style.textAlign === 'right') { tx = absX + absW; align = 'right'; }

        let ty = absY + fontSize/3; 
        if (style.verticalAlign === 'middle' || !style.verticalAlign && (el.type === 'day_number' || el.type === 'box')) {
             ty = absY + (absH / 2) + (fontSize * 0.352 / 2); 
        }

        if (style.textTransform === 'uppercase') text = text.toUpperCase();
        if (style.textTransform === 'lowercase') text = text.toLowerCase();

        if (el.type === 'text' || el.type === 'quote' || el.type === 'holiday_list') {
            const splitText = doc.splitTextToSize(text, absW);
            doc.text(splitText, tx, ty + 4, { align, baseline: 'top' });
        } else {
            doc.text(text, tx, ty, { align });
        }
    }

    // Special: Full Calendar
    if (el.type === 'full_calendar' && day) {
        const cols = style.monthsPerRow || 3;
        const cellW = absW / cols;
        const cellH = absH / Math.ceil(12/cols);

        for(let m=0; m<12; m++) {
            const c = m % cols;
            const r = Math.floor(m / cols);
            const mx = absX + (c * cellW);
            const my = absY + (r * cellH);

            doc.setFontSize(8);
            doc.setFont(fontConfig.font, 'bold');
            doc.text(getMonthName(m), mx + cellW/2, my + 4, { align: 'center' });

            doc.setDrawColor(200, 200, 200);
            doc.rect(mx + 2, my + 6, cellW - 4, cellH - 8);
        }
    }

    // Special: Table
    if (el.type === 'table') {
        const rows = style.table?.rows || 10;
        const cols = style.table?.cols || 2;
        const userRowHeight = style.table?.rowHeight;
        const rowH = userRowHeight ? (userRowHeight * 0.264583) : (absH / rows);
        const colWs = style.table?.columnWidths || Array(cols).fill(100/cols);

        let curY = absY;
        doc.setDrawColor(200, 200, 200);
        doc.setLineWidth(0.1);

        for (let r=0; r<rows; r++) {
            let curX = absX;
            for (let c=0; c<cols; c++) {
                const cellW = (colWs[c] / 100) * absW;
                doc.rect(curX, curY, cellW, rowH);
                const content = style.table?.cellContent?.[`${r}-${c}`];
                if (content) {
                    doc.setFontSize(8);
                    doc.text(content, curX + 2, curY + rowH/2 + 2);
                }
                curX += cellW;
            }
            curY += rowH;
        }
    }
};

export const generateAndDownloadPDF = async (config: AgendaConfig, generatedDays: DayData[], quotes: string[], onProgress: (progress: number) => void) => {
    const format = config.pageSize.toLowerCase();
    const orientation = config.orientation === 'portrait' ? 'p' : 'l';
    const doc = new jsPDF({ orientation, unit: "mm", format, compress: true });
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();

    const getSafeGeometry = (pageNum: number) => {
        const isEven = pageNum % 2 === 0;
        let marginLeft, marginRight;
        if (config.mirrorEvenPages && isEven) { marginLeft = config.margins.outside; marginRight = config.margins.inside; } 
        else { marginLeft = config.margins.inside; marginRight = config.margins.outside; }
        const marginTop = config.margins.top;
        const marginBottom = config.margins.bottom;
        return { marginLeft, marginTop, safeW: pageW - marginLeft - marginRight, safeH: pageH - marginTop - marginBottom };
    };

    const getElementsForPage = (elements: LayoutElement[], pageNum: number): LayoutElement[] => {
        const isEven = pageNum % 2 === 0;
        if (config.mirrorEvenPages && isEven) {
            return elements.map(el => {
                const newX = 100 - el.x - el.w;
                let newTextAlign = el.style.textAlign;
                if (newTextAlign === 'left') newTextAlign = 'right'; else if (newTextAlign === 'right') newTextAlign = 'left';
                return { ...el, x: newX, style: { ...el.style, textAlign: newTextAlign } };
            });
        }
        return elements;
    };

    let globalPageCount = 0;
    const totalPages = config.introPages.length + (config.layoutType === '1_per_page' ? generatedDays.length : config.layoutType === '2_per_page' ? Math.ceil(generatedDays.length / 2) : Math.ceil(generatedDays.length));

    for (const page of config.introPages) {
        if (globalPageCount > 0) doc.addPage(format, orientation);
        globalPageCount++;
        const geo = getSafeGeometry(globalPageCount);
        const elements = getElementsForPage(page.elements, globalPageCount);
        elements.forEach(el => renderElementToPDF(doc, el, null, undefined, geo.safeW, geo.safeH, geo.marginLeft, geo.marginTop));
        onProgress(Math.round((globalPageCount / totalPages) * 100));
        await new Promise(r => setTimeout(r, 0)); 
    }

    if (config.layoutType === '1_per_page') {
        for (const day of generatedDays) {
            doc.addPage(format, orientation);
            globalPageCount++;
            const geo = getSafeGeometry(globalPageCount);
            const elements = getElementsForPage(config.elements, globalPageCount);
            elements.forEach(el => renderElementToPDF(doc, el, day, quotes[day.month], geo.safeW, geo.safeH, geo.marginLeft, geo.marginTop));
            if (globalPageCount % 10 === 0) { onProgress(Math.round((globalPageCount / totalPages) * 100)); await new Promise(r => setTimeout(r, 0)); }
        }
    } 
    else if (config.layoutType === '2_per_page') {
        for (let i = 0; i < generatedDays.length; i += 2) {
            doc.addPage(format, orientation);
            globalPageCount++;
            const geo = getSafeGeometry(globalPageCount);
            const day1 = generatedDays[i];
            const day2 = generatedDays[i+1];
            const elements = getElementsForPage(config.elements, globalPageCount);
            elements.forEach(el => { const halfH_El = { ...el, h: el.h / 2, y: el.y / 2 }; renderElementToPDF(doc, halfH_El, day1, quotes[day1.month], geo.safeW, geo.safeH, geo.marginLeft, geo.marginTop); });
            if (day2) { elements.forEach(el => { const halfH_El = { ...el, h: el.h / 2, y: (el.y / 2) + 50 }; renderElementToPDF(doc, halfH_El, day2, quotes[day2.month], geo.safeW, geo.safeH, geo.marginLeft, geo.marginTop); }); const midY = geo.marginTop + (geo.safeH / 2); doc.setDrawColor(200, 200, 200); doc.setLineDash([2, 2], 0); doc.line(0, midY, pageW, midY); doc.setLineDash([], 0); }
            if (globalPageCount % 10 === 0) { onProgress(Math.round((globalPageCount / totalPages) * 100)); await new Promise(r => setTimeout(r, 0)); }
        }
    }
    else if (config.layoutType === '1_per_page_weekend_shared') {
        let i = 0;
        while (i < generatedDays.length) {
            const day = generatedDays[i];
            const isSaturday = day.dayOfWeek === 6;
            doc.addPage(format, orientation);
            globalPageCount++;
            const geo = getSafeGeometry(globalPageCount);
            const elements = getElementsForPage(config.elements, globalPageCount);
            if (isSaturday) {
                elements.forEach(el => { const halfH_El = { ...el, h: el.h / 2, y: el.y / 2 }; renderElementToPDF(doc, halfH_El, day, quotes[day.month], geo.safeW, geo.safeH, geo.marginLeft, geo.marginTop); });
                const nextDay = generatedDays[i+1];
                if (nextDay) { elements.forEach(el => { const halfH_El = { ...el, h: el.h / 2, y: (el.y / 2) + 50 }; renderElementToPDF(doc, halfH_El, nextDay, quotes[nextDay.month], geo.safeW, geo.safeH, geo.marginLeft, geo.marginTop); }); const midY = geo.marginTop + (geo.safeH / 2); doc.setDrawColor(200, 200, 200); doc.setLineDash([2, 2], 0); doc.line(0, midY, pageW, midY); doc.setLineDash([], 0); }
                i += 2; 
            } else {
                elements.forEach(el => renderElementToPDF(doc, el, day, quotes[day.month], geo.safeW, geo.safeH, geo.marginLeft, geo.marginTop));
                i += 1;
            }
            if (globalPageCount % 10 === 0) { onProgress(Math.round((globalPageCount / totalPages) * 100)); await new Promise(r => setTimeout(r, 0)); }
        }
    }

    onProgress(100);
    doc.save(`Agenda_${config.year}.pdf`);
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AgendaConfig, User, DayData, LayoutElement, ElementType, PageLayoutType, TextStyleConfig, PageSize, PageOrientation } from '../../types';
