  const renderPrintLayout = (limitStart?: number, limitEnd?: number, maxRenderCount?: number) => {
    const pages: React.ReactNode[] = [];
    const pageStyle = { width: `${PAGE_WIDTH_MM}mm`, height: `${PAGE_HEIGHT_MM}mm` };
    const borderStyle = showMargins ? 'border border-indigo-200 border-dashed' : '';
    let pageCount = 0;
    const renderPageContainer = (children: React.ReactNode, key: string | number) => {
        pageCount++;
        if (limitStart !== undefined && limitEnd !== undefined) { if (pageCount < limitStart || pageCount > limitEnd) return null; }
        const isEven = pageCount % 2 === 0;
        const marginLeft = isEven ? config.margins.outside : config.margins.inside;
        const marginRight = isEven ? config.margins.inside : config.margins.outside;
        const pagePadding = `${config.margins.top}mm ${marginRight}mm ${config.margins.bottom}mm ${marginLeft}mm`;
        return (<div id={`preview-page-${pageCount}`} key={key} className="bg-white shadow print:shadow-none print-break-page relative box-border overflow-hidden mx-auto mb-8 print:mb-0 shrink-0" style={{ ...pageStyle, padding: pagePadding }}><div className={`w-full h-full relative ${borderStyle} print:border-none`}>{children}</div><div className={`absolute bottom-1 text-[8px] text-gray-300 no-print ${isEven ? 'left-2' : 'right-2'}`}>Pág {pageCount} ({isEven ? 'Par/Verso' : 'Ímpar/Frente'})</div></div>);
    };
