    if (layoutType === '1_per_page') { effectiveDays.forEach(day => { const isEven = (pageCount + 1) % 2 === 0; const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements; const container = renderPageContainer(renderTemplate(elementsToRender, day, false), day.date.toISOString()); if(container) pages.push(container); }); } 
    else if (layoutType === '2_per_page') { for (let i = 0; i < effectiveDays.length; i += 2) { const isEven = (pageCount + 1) % 2 === 0; const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements; const container = renderPageContainer(<div className="flex flex-col h-full"><div className={`flex-1 relative border-b border-dashed border-gray-200 pb-2 mb-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}><div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, effectiveDays[i], false)}</div></div><div className={`flex-1 relative pt-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}>{effectiveDays[i+1] ? (<div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, effectiveDays[i+1], false)}</div>) : null}</div></div>, i); if(container) pages.push(container); } } 
