                      <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Espessura</label><input type="number" min="0" max="20" value={selectedElement.style.borderWidth ?? 1} onChange={(e) => updateElementStyle(selectedElement.id, { borderWidth: parseInt(e.target.value) })} className="w-full text-xs p-1.5 border border-gray-200 rounded" /></div>
                  </div>
                  <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Arredondamento (px)</label><input type="range" min="0" max="50" value={selectedElement.style.borderRadius || 0} onChange={(e) => updateElementStyle(selectedElement.id, { borderRadius: parseInt(e.target.value) })} className="w-full accent-indigo-600" /></div>
