                  <div className="w-full max-w-md bg-white/10 p-6 rounded-2xl border border-white/20 backdrop-blur-xl shadow-2xl flex flex-col items-center">
                        <Loader2 className="w-12 h-12 animate-spin mb-4 text-indigo-400" />
                        <h2 className="text-xl font-bold mb-1">Gerando Documento...</h2>
                        <p className="text-sm opacity-70 mb-6 text-center">Processando página {config.introPages.length + renderedPrintCount} de {totalPages}...</p>
                        <div className="w-full h-3 bg-white/10 rounded-full overflow-hidden mb-6"><div className="h-full bg-indigo-500 transition-all duration-300 ease-out relative" style={{ width: `${progressPercent}%` }}><div className="absolute inset-0 bg-white/20 animate-[shimmer_1s_infinite] w-full h-full transform skew-x-12"></div></div></div>
                        <button onClick={cancelPrint} className="w-full py-3 px-4 rounded-lg bg-white/10 hover:bg-white/20 text-white font-medium text-sm transition-colors border border-white/10">Cancelar</button>
                  </div>
              ) : (
                  <div className="w-full max-w-lg bg-white p-8 rounded-2xl shadow-2xl flex flex-col items-center text-gray-800 animate-in zoom-in duration-300">
                      <div className="bg-indigo-100 p-3 rounded-full mb-4"><FileDown className="w-8 h-8 text-indigo-600" /></div>
                      <h2 className="text-2xl font-bold mb-2 text-center">Arquivo Pronto para Download</h2>
                      <p className="text-sm text-gray-500 mb-6 text-center max-w-sm">O miolo da agenda foi gerado com sucesso. Siga as instruções abaixo para salvar o arquivo PDF corretamente.</p>
                      <div className="w-full bg-blue-50 border border-blue-100 rounded-xl p-4 mb-6"><h4 className="text-sm font-bold text-blue-800 mb-2 flex items-center gap-2"><Info className="w-4 h-4"/> Como salvar:</h4><ol className="list-decimal list-inside text-sm text-blue-900/80 space-y-2"><li>Clique no botão <strong>"Baixar PDF Agora"</strong> abaixo.</li><li>Na janela de impressão que abrir, mude o <strong>Destino</strong> para <span className="font-bold bg-white px-1 rounded border border-blue-200 text-blue-700">Salvar como PDF</span>.</li><li>Defina as margens como <strong>"Nenhuma"</strong> se disponível.</li><li>Clique em <strong>Salvar</strong>.</li></ol></div>
                      <div className="flex gap-3 w-full"><button onClick={cancelPrint} className="flex-1 py-3 px-4 rounded-lg bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium text-sm transition-colors">Cancelar</button><button onClick={() => window.print()} className="flex-1 py-3 px-4 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-sm transition-all shadow-lg flex items-center justify-center gap-2"><FileDown className="w-4 h-4"/> Baixar PDF Agora</button></div>
                  </div>
              )}
          </div>
      )}

      {variantModal && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/20 backdrop-blur-sm no-print" onClick={() => setVariantModal(null)}>
