                  <div className="flex items-center justify-between p-4 border-b border-gray-100"><h3 className="text-sm font-bold text-gray-800 uppercase tracking-wide">Escolha o estilo</h3><button onClick={() => setVariantModal(null)} className="text-gray-400 hover:text-red-500"><X className="w-5 h-5"/></button></div>
                  <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto max-h-[60vh]">
                      {ELEMENT_VARIANTS[variantModal.type]?.map((variant, idx) => (<div key={idx} onClick={() => addElement(variantModal.type, variantModal.label, variant.styleOverride, variant.defaultSize)} className="border border-gray-200 rounded-lg p-4 hover:border-indigo-500 hover:bg-indigo-50 cursor-pointer transition-all flex flex-col items-center gap-3 group"><div className="text-center"><div className="text-sm font-bold text-gray-700 group-hover:text-indigo-700">{variant.name}</div><div className="text-xs text-gray-400">{variant.description}</div></div></div>))}
                  </div>
              </div>
          </div>
      )}

      <div className="flex-1 flex flex-col overflow-hidden no-print">
          <header className="bg-white border-b border-gray-200 h-14 flex items-center justify-between px-4 z-20 shrink-0">
