                {onConfigure && (<button onClick={onConfigure} className="p-1.5 rounded-md text-gray-500 hover:bg-gray-100 hover:text-indigo-600 mr-2" title="Voltar para Configuração Inicial"><Settings className="w-5 h-5" /></button>)}
