                <button onClick={() => setSnapToObjects(!snapToObjects)} className={`p-1.5 rounded-md transition-all ${snapToObjects ? 'bg-indigo-100 text-indigo-700 ring-1 ring-indigo-500' : 'text-gray-400 hover:bg-gray-100'}`} title={snapToObjects ? "Alinhamento Inteligente Ativado" : "Ativar Alinhamento Inteligente"}><Magnet className="w-5 h-5" /></button>
                <button onClick={() => setShowAlignment(!showAlignment)} className={`p-1.5 rounded-md ${showAlignment ? 'bg-indigo-50 text-indigo-600 ring-1' : 'text-gray-400'}`} title="Ferramentas de Alinhamento"><BoxSelect className="w-5 h-5" /></button>
