                    <div className="flex space-x-1 bg-gray-100 p-1 rounded-lg mb-4">
                        <button onClick={() => { setEditMode('daily'); setSelectedId(null); }} className={`flex-1 py-1.5 px-2 text-[10px] font-bold uppercase rounded-md transition-all ${editMode === 'daily' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}>Template Diário</button>
                        <button onClick={() => { setEditMode('intro'); setSelectedId(null); if (!currentIntroPageId && config.introPages.length > 0) setCurrentIntroPageId(config.introPages[0].id); }} className={`flex-1 py-1.5 px-2 text-[10px] font-bold uppercase rounded-md transition-all ${editMode === 'intro' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}>Páginas Iniciais</button>
                    </div>
                    {editMode === 'intro' && (
                        <div className="space-y-2">
                            <div className="flex items-center justify-between text-[10px] text-gray-500 font-bold uppercase mb-1"><span>Lista de Páginas</span><button onClick={addIntroPage} className="text-indigo-600 hover:text-indigo-800 p-1 bg-indigo-50 rounded"><Plus className="w-3 h-3" /></button></div>
                            <div className="space-y-1 max-h-40 overflow-y-auto pr-1 custom-scrollbar">
                                {config.introPages.map(page => (<div key={page.id} onClick={() => { setCurrentIntroPageId(page.id); setSelectedId(null); }} className={`group flex items-center justify-between p-2 rounded text-xs cursor-pointer border transition-all ${currentIntroPageId === page.id ? 'bg-indigo-50 border-indigo-300 text-indigo-700 font-medium' : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'}`}><div className="flex items-center gap-2 truncate flex-1"><FileText className="w-3 h-3 flex-shrink-0" /><input type="text" value={page.name} onChange={(e) => renameIntroPage(page.id, e.target.value)} className="bg-transparent border-none p-0 w-full focus:ring-0 text-xs font-inherit cursor-pointer focus:bg-white focus:cursor-text" onClick={(e) => e.stopPropagation()}/></div><button onClick={(e) => { e.stopPropagation(); deleteIntroPage(page.id); }} className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 p-1"><Trash2 className="w-3 h-3" /></button></div>))}
                                {config.introPages.length === 0 && <div className="text-center py-2 text-xs text-gray-400 italic">Nenhuma página. Clique em + para adicionar.</div>}
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-4 flex-1 overflow-y-auto">
                    <div className="flex items-center mb-3 text-gray-400"><Layout className="w-4 h-4 mr-2" /><h3 className="text-xs font-semibold uppercase tracking-wider">Elementos</h3></div>
                    <div className="grid grid-cols-4 gap-2">
                        {editMode === 'daily' && (<><button onClick={() => setVariantModal({type: 'day_number', label: 'Número'})} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="font-bold text-xs">24</span></button><button onClick={() => setVariantModal({type: 'day_name', label: 'Dia'})} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="text-[10px] font-bold">SEG</span></button><button onClick={() => setVariantModal({type: 'month_name', label: 'Mês'})} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="text-[10px]">MÊS</span></button></>)}
                        <button onClick={() => addElement('text', 'Texto')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Texto"><Type className="w-4 h-4"/></button>
                        <button onClick={() => addElement('box', 'Caixa')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Caixa"><Square className="w-4 h-4"/></button>
                        <button onClick={() => addElement('circle', 'Círculo')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Círculo"><Circle className="w-4 h-4"/></button>
                        <button onClick={() => setVariantModal({type: 'lines', label: 'Pautas'})} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Pautas / Linhas"><ListTodo className="w-4 h-4"/></button>
                        <button onClick={() => addElement('note_grid', 'Grid Pontilhado', { opacity: 0.5 }, { w: 40, h: 20 })} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Grid Pontilhado"><Grid3X3 className="w-4 h-4"/></button>
                        <button onClick={() => addElement('lines', 'Divisória', { color: '#d1d5db', lineSpacing: 2 }, { w: 50, h: 2 })} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Linha Divisória"><Minus className="w-4 h-4"/></button>
                        <button onClick={() => addElement('mini_calendar', 'Calendário')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Mini Calendário"><CalendarDays className="w-4 h-4"/></button>
                        <button onClick={() => setVariantModal({type: 'vector_flower', label: 'Vetor'})} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Vetores"><Flower className="w-4 h-4"/></button>
                        <button onClick={() => openElementSelector('moon', 'Fase da Lua')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Fases da Lua"><Moon className="w-4 h-4"/></button>
                        <button onClick={() => addElement('habit_tracker', 'Habit Tracker')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Habit Tracker"><span className="text-[8px] font-bold">HAB</span></button>
                        <button onClick={() => addElement('table', 'Tabela')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Tabela de Horários"><TableIcon className="w-4 h-4"/></button>
                        <button onClick={() => addElement('lines', 'Pontilhado', { color: '#d1d5db', lineSpacing: 24, variant: 'dotted' })} className="h-10 flex flex-col items-center justify-center border rounded hover:bg-indigo-50" title="Linha Pontilhada"><div className="w-4 h-0.5 border-t border-dotted border-gray-400"></div></button>
                        {editMode === 'intro' && (<><button onClick={() => addElement('full_calendar', 'Calendário Anual')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Calendário Anual (Grid)"><Grid className="w-4 h-4 mr-1" /></button><button onClick={() => addElement('holiday_list', 'Lista Feriados')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Lista de Feriados"><List className="w-4 h-4 mr-1" /></button></>)}
                    </div>
                </div>
            </aside>

            <main className="flex-1 bg-gray-200 overflow-hidden relative flex flex-col items-center">
                {activeTab === 'editor' && (
                    <div className="flex-1 w-full flex flex-col items-center p-4 overflow-hidden relative">
                        {/* ... Floating Panels (Alignment, Layers) ... */}
                        {showAlignment && (
                            <div className="absolute top-20 right-[290px] bg-white rounded-lg shadow-xl border border-gray-200 flex flex-col z-40 no-print animate-in fade-in zoom-in-95 duration-200">
                                <div className="flex items-center justify-between p-2 border-b border-gray-100 bg-gray-50 rounded-t-lg"><span className="text-[10px] font-bold text-gray-500 uppercase">Alinhamento</span><button onClick={() => setShowAlignment(false)} className="text-gray-400 hover:text-red-500"><X className="w-3 h-3" /></button></div>
                                <div className="p-2 grid grid-cols-3 gap-1"><button onClick={() => alignElement('left')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Esquerda"><AlignStartHorizontal className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('center')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Centralizar Horizontalmente"><AlignCenterHorizontal className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('right')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Direita"><AlignEndHorizontal className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('top')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar ao Topo"><ArrowUpToLine className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('middle')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Centralizar Verticalmente"><AlignCenterVertical className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('bottom')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Base"><ArrowDownToLine className="w-4 h-4 mx-auto" /></button></div>
                            </div>
                        )}

                        {showLayers && (
                            <div className="absolute left-4 top-20 w-64 bg-white rounded-lg shadow-xl border border-gray-200 flex flex-col max-h-[50vh] z-40 no-print animate-in fade-in zoom-in-95 duration-200">
                                <div className="flex items-center justify-between p-3 border-b border-gray-100 bg-gray-50 rounded-t-lg"><div className="flex items-center text-gray-500 font-bold text-xs uppercase tracking-wide"><Layers className="w-3 h-3 mr-1.5" /> Camadas</div><button onClick={() => setShowLayers(false)} className="text-gray-400 hover:text-red-500"><X className="w-4 h-4" /></button></div>
                                <div className="p-2 overflow-y-auto custom-scrollbar">{getActiveElements().slice().reverse().map((el) => (<div key={el.id} onClick={() => setSelectedId(el.id)} className={`flex items-center p-2 rounded text-xs cursor-pointer border group/layer mb-1 ${selectedId === el.id ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'}`}><span className="flex-1 truncate font-medium">{el.name || el.type}</span><div className="flex items-center opacity-0 group-hover/layer:opacity-100 transition-opacity"><button onClick={(e) => moveLayer(el.id, 'up')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-0.5"><ChevronUp className="w-3 h-3" /></button><button onClick={(e) => moveLayer(el.id, 'down')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-1"><ChevronDown className="w-3 h-3" /></button><button onClick={(e) => { e.stopPropagation(); removeElement(el.id); }} className="text-gray-400 hover:text-red-500 p-1 hover:bg-red-50 rounded"><Trash2 className="w-3 h-3" /></button></div></div>))}{getActiveElements().length === 0 && <div className="text-center text-gray-400 text-xs py-4">Sem camadas</div>}</div>
                            </div>
