                <div className={`w-full h-full relative ${isWrapperType ? (shouldClip ? 'overflow-hidden flex flex-col' : 'flex flex-col') : 'flex items-center'}`} style={{ justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start'), ...(!isWrapperType ? el.style : {}) }}>
                    {isWrapperType ? (<ElementRenderer element={el} dayData={d} quote={quotes[d.month]} isEditor={isEditor} isSelected={isSelected} onContentChange={updateElementContent} onTableResizeStart={handleTableColumnResizeStart} onTableCellChange={updateTableCell} onTableCellFocus={handleTableCellFocus} globalCalendarStyle={globalStyle} />) : <span style={{ pointerEvents: 'none' }}><ElementRenderer element={el} dayData={d} quote={quotes[d.month]} isEditor={isEditor} isSelected={isSelected} onContentChange={updateElementContent} /></span>}
