  const getMirroredElements = (elements: LayoutElement[]): LayoutElement[] => {
      if (!config.mirrorEvenPages) return elements;
      return elements.map(el => {
          const newX = 100 - el.x - el.w;
          let newTextAlign = el.style.textAlign;
          if (newTextAlign === 'left') newTextAlign = 'right'; else if (newTextAlign === 'right') newTextAlign = 'left';
          return { ...el, x: newX, style: { ...el.style, textAlign: newTextAlign } };
      });
  };

  const renderEditorPage = () => {
    const paddingStyle = { paddingTop: `${config.margins.top * EDITOR_SCALE}px`, paddingBottom: `${config.margins.bottom * EDITOR_SCALE}px`, paddingLeft: `${config.margins.inside * EDITOR_SCALE}px`, paddingRight: `${config.margins.outside * EDITOR_SCALE}px` };
    const containerClass = `bg-white shadow-2xl relative transition-all duration-300 ease-in-out flex flex-col`;
    const containerStyle = { width: `${EDITOR_WIDTH_PX}px`, height: `${EDITOR_HEIGHT_PX}px`, ...paddingStyle };
    const usefulAreaClass = `w-full h-full relative ${showMargins ? 'outline outline-1 outline-dashed outline-indigo-300' : ''}`;
    if (editMode === 'intro') { return <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(getActiveElements(), null, true, true)}</div></div>; }
    const activeElements = config.elements;
    if (config.layoutType === '1_per_page') return <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(activeElements, null, true, true)}</div></div>;
    if (config.layoutType === '2_per_page') return <div className={containerClass} style={containerStyle}><div className={`${usefulAreaClass} flex flex-col`}><div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(activeElements, null, true, true)}</div><div className="flex-1 relative overflow-hidden">{renderTemplate(activeElements, null, true, false)}</div></div></div>;
    if (config.layoutType === '1_per_page_weekend_shared') return editorViewMode === 'standard' ? <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(activeElements, null, true, true)}</div></div> : <div className={containerClass} style={containerStyle}><div className={`${usefulAreaClass} flex flex-col`}><div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(activeElements, null, true, true)}</div><div className="flex-1 relative overflow-hidden">{renderTemplate(activeElements, null, true, false)}</div></div></div>;
    return null;
  };

  const renderPrintLayout = (limitStart?: number, limitEnd?: number, maxRenderCount?: number) => {
    const pages: React.ReactNode[] = [];
    const pageStyle = { width: `${PAGE_WIDTH_MM}mm`, height: `${PAGE_HEIGHT_MM}mm` };
    const borderStyle = showMargins ? 'border border-indigo-200 border-dashed' : '';
    let pageCount = 0;
    const renderPageContainer = (children: React.ReactNode, key: string | number) => {
        pageCount++;
        if (limitStart !== undefined && limitEnd !== undefined) { if (pageCount < limitStart || pageCount > limitEnd) return null; }
        const isEven = pageCount % 2 === 0;
        const marginLeft = isEven ? config.margins.outside : config.margins.inside;
        const marginRight = isEven ? config.margins.inside : config.margins.outside;
        const pagePadding = `${config.margins.top}mm ${marginRight}mm ${config.margins.bottom}mm ${marginLeft}mm`;
        return (<div id={`preview-page-${pageCount}`} key={key} className="bg-white shadow print:shadow-none print-break-page relative box-border overflow-hidden mx-auto mb-8 print:mb-0 shrink-0" style={{ ...pageStyle, padding: pagePadding }}><div className={`w-full h-full relative ${borderStyle} print:border-none`}>{children}</div><div className={`absolute bottom-1 text-[8px] text-gray-300 no-print ${isEven ? 'left-2' : 'right-2'}`}>Pág {pageCount} ({isEven ? 'Par/Verso' : 'Ímpar/Frente'})</div></div>);
    };
    config.introPages.forEach(page => { const isEven = (pageCount + 1) % 2 === 0; const elementsToRender = isEven ? getMirroredElements(page.elements) : page.elements; const container = renderPageContainer(renderTemplate(elementsToRender, null, false), page.id); if(container) pages.push(container); });
    const days = generatedData;
    const effectiveDays = (limitStart === undefined && maxRenderCount !== undefined) ? days.slice(0, maxRenderCount) : days;
    const { layoutType } = config;
    if (layoutType === '1_per_page') { effectiveDays.forEach(day => { const isEven = (pageCount + 1) % 2 === 0; const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements; const container = renderPageContainer(renderTemplate(elementsToRender, day, false), day.date.toISOString()); if(container) pages.push(container); }); } 
    else if (layoutType === '2_per_page') { for (let i = 0; i < effectiveDays.length; i += 2) { const isEven = (pageCount + 1) % 2 === 0; const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements; const container = renderPageContainer(<div className="flex flex-col h-full"><div className={`flex-1 relative border-b border-dashed border-gray-200 pb-2 mb-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}><div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, effectiveDays[i], false)}</div></div><div className={`flex-1 relative pt-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}>{effectiveDays[i+1] ? (<div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, effectiveDays[i+1], false)}</div>) : null}</div></div>, i); if(container) pages.push(container); } } 
    else if (layoutType === '1_per_page_weekend_shared') { let i = 0; while (i < effectiveDays.length) { const day = effectiveDays[i]; const isWeekend = day.dayOfWeek === 6; const isEven = (pageCount + 1) % 2 === 0; const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements; if (isWeekend) { if (!effectiveDays[i+1] && limitStart === undefined) break; const container = renderPageContainer(<div className="flex flex-col h-full"><div className="flex-1 relative border-b border-dashed border-gray-300 pb-2 mb-2 overflow-hidden"><div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, day, false)}</div></div><div className="flex-1 relative pt-2 overflow-hidden">{effectiveDays[i+1] ? (<div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, effectiveDays[i+1], false)}</div>) : null}</div></div>, `we-${i}`); if(container) pages.push(container); i += 2; } else { const container = renderPageContainer(renderTemplate(elementsToRender, day, false), day.date.toISOString()); if(container) pages.push(container); i += 1; } } }
    return pages;
  };

