                        <button onClick={() => addElement('lines', 'Divisória', { color: '#d1d5db', lineSpacing: 2 }, { w: 50, h: 2 })} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Linha Divisória"><Minus className="w-4 h-4"/></button>
