                        <button onClick={() => addElement('habit_tracker', 'Habit Tracker')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Habit Tracker"><span className="text-[8px] font-bold">HAB</span></button>
                        <button onClick={() => addElement('table', 'Tabela')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Tabela de Horários"><TableIcon className="w-4 h-4"/></button>
                        <button onClick={() => addElement('lines', 'Pontilhado', { color: '#d1d5db', lineSpacing: 24, variant: 'dotted' })} className="h-10 flex flex-col items-center justify-center border rounded hover:bg-indigo-50" title="Linha Pontilhada"><div className="w-4 h-0.5 border-t border-dotted border-gray-400"></div></button>
                        {editMode === 'intro' && (<><button onClick={() => addElement('full_calendar', 'Calendário Anual')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Calendário Anual (Grid)"><Grid className="w-4 h-4 mr-1" /></button><button onClick={() => addElement('holiday_list', 'Lista Feriados')} className="h-10 flex items-center justify-center border rounded hover:bg-indigo-50" title="Lista de Feriados"><List className="w-4 h-4 mr-1" /></button></>)}
                    </div>
                </div>
            </aside>

            <main className="flex-1 bg-gray-200 overflow-hidden relative flex flex-col items-center">
                {activeTab === 'editor' && (
                    <div className="flex-1 w-full flex flex-col items-center p-4 overflow-hidden relative">
                        {/* ... Floating Panels (Alignment, Layers) ... */}
                        {showAlignment && (
                            <div className="absolute top-20 right-[290px] bg-white rounded-lg shadow-xl border border-gray-200 flex flex-col z-40 no-print animate-in fade-in zoom-in-95 duration-200">
                                <div className="flex items-center justify-between p-2 border-b border-gray-100 bg-gray-50 rounded-t-lg"><span className="text-[10px] font-bold text-gray-500 uppercase">Alinhamento</span><button onClick={() => setShowAlignment(false)} className="text-gray-400 hover:text-red-500"><X className="w-3 h-3" /></button></div>
                                <div className="p-2 grid grid-cols-3 gap-1"><button onClick={() => alignElement('left')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Esquerda"><AlignStartHorizontal className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('center')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Centralizar Horizontalmente"><AlignCenterHorizontal className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('right')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Direita"><AlignEndHorizontal className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('top')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar ao Topo"><ArrowUpToLine className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('middle')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Centralizar Verticalmente"><AlignCenterVertical className="w-4 h-4 mx-auto" /></button><button onClick={() => alignElement('bottom')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Base"><ArrowDownToLine className="w-4 h-4 mx-auto" /></button></div>
                            </div>
