        const specialDaysConfig = effectiveStyle?.specialDays || { highlightSundays: false, highlightHolidays: false, style: { color: '#ff0000', fontWeight: 'bold', fontSize: 10, fontFamily: 'Inter', textAlign: 'center', textTransform: 'none', letterSpacing: 0 } };

