interface ElementRendererProps {
  element: LayoutElement;
  dayData: DayData;
  quote?: string;
  isEditor: boolean;
  isSelected?: boolean;
  onContentChange?: (id: string, content: string) => void;
  onTableResizeStart?: (e: React.MouseEvent, elementId: string, colIndex: number) => void;
  onTableCellChange?: (elementId: string, row: number, col: number, text: string) => void;
  onTableCellFocus?: (elementId: string, row: number, col: number) => void;
  globalCalendarStyle?: LayoutElement['style']['fullCalendar'];
}

export const ElementRenderer: React.FC<ElementRendererProps> = memo((props) => {
  const { element } = props;

  // Simple dispatch logic based on element type
  if (['table'].includes(element.type)) {
      return <TableElement {...props} style={element.style} />;
  }

  if (['mini_calendar', 'full_calendar'].includes(element.type)) {
      return <CalendarElement {...props} style={element.style} />;
  }

  if (['box', 'circle', 'lines'].includes(element.type)) {
      return <ShapeElement {...props} style={element.style} />;
  }

  if (['text', 'quote', 'holiday', 'holiday_list'].includes(element.type)) {
      return <TextElement {...props} style={element.style} />;
  }

  if (['day_number', 'month_name', 'day_name', 'year'].includes(element.type)) {
      return <PlaceholderElement {...props} style={element.style} />;
  }

  if (['moon', 'vector_flower', 'habit_tracker', 'note_grid'].includes(element.type)) {
      return <GraphicsElement {...props} style={element.style} />;
  }

  return null;
});

